## 组合技巧（序列示例）

### "权力登场"
```
片段 1: 6B FPV 无人机 — 穿越城市定位主体
片段 2: 3A 斯坦尼康跟随 — 穿越复杂空间跟随
片段 3: 3D 推进 — 落在面部捕捉情感节拍
```

### "梦境记忆"
```
片段 1: 5A 王家卫漂移 — 碎片化的夜间游荡
片段 2: 2D 镜子平移 — 反射与现实分裂
片段 3: 1A 眩晕变焦 — 现实扭曲
片段 4: 2A 塔可夫斯基漂浮 — 漂入记忆
```

### "史诗揭示"
```
片段 1: 4A 库布里克单点 — 沿走廊接近
片段 2: 1D 俯冲下降 — 上帝之眼下降
片段 3: 2C 维伦纽瓦尺度揭示 — 巨大主体揭晓
```

