## 说明
使用此指南优化电商产品视频的内容类型。重点展示合身度、动态效果和产品表现。

- **顺序**：遵循 展示 -> 合身/使用测试 -> 动态/穿着验证 -> 细节特写 -> 最终效果 的结构。
- **视觉效果**：利用镜子构图、开箱特写和动态测试（行走、转身或涂抹）来建立产品可信度。
- **脚本**：将视频分为开场（0:00-0:03）、中间（0:03-0:18）和结尾（0:18-0:25）三个部分。

## 使用时机
- **适用场景**：服装、配饰、美妆、鞋类或可穿戴科技产品，需展示合身度、舒适度或尺寸比例。
- **不适用场景**：无法“穿戴”或通过物理使用测试的产品；纯数字或非实体服务。

## 输出要求
- **开场钩子**：以真实的合身或使用测试开始，而非静态展示。
- **验证镜头**：包含特定镜头，证明产品在动态下的耐用性、舒适度、质感或合身度。
- **结尾限制**：不得包含“立即点击”、“向上滑动”或“简介链接”等行动号召（CTA）短语。聚焦于品牌主导或愿景型标语。

## 工作流程
1. **开场**：执行开箱、镜子展示或初始使用钩子。
2. **中间**：进行试穿、合身调整和动态/使用测试。
3. **结尾**：展示最终产品主镜头，搭配品牌导向的文字或画外音。

## 示例
- **开场**：模特对着镜子做动作；画外音：“如果看起来不错，它还得通过真正的合身测试。”
- **中间**：产品质感/合身度特写；文字叠加：“动态中的证明。”
- **结尾**：模特穿着产品的主镜头；画外音：“从第一次试穿起就感觉自然。”
',
  source='official', sort_order=9, cover_url=NULL, skill_code='cn09', version=0, is_delete=0, gmt_modified=NOW() WHERE id=8;
UPDATE skill SET name='Split Screen Product Ad', description='为分屏产品视频广告提供格式和脚本指导。适用于需要并排或上下对比的产品演示内容设计，例如“前后对比”或“外观与细节”视图。', content='---
name: custom-ecom-split-screen
description: 为分屏产品视频广告提供格式和脚本指导。适用于需要并排或上下对比的产品演示内容设计，例如“前后对比”或“外观与细节”视图。
version: 0.1.0
---

## 说明

- 将此指南作为电商产品视频的广告格式叠加层使用。
- 采用上下或左右分屏设计布局。
- 确保每个面板有明确用途（例如“使用中”与“细节”，或“之前”与“之后”）。
- 保持面板视觉同步，以维持观众方向感。
- 使用简洁边框、对齐的运动和最小化标签，避免视觉杂乱。
- 始终确保至少一个面板中产品可见。
- 谨慎切换布局，确保设计意图明确。

## 使用时机

- **适用场景**：比较产品状态、展示生活方式背景与特写功能对比，或演示“问题 vs. 结果”场景。
- **不适用场景**：当产品优势通过单一连续广角镜头即可最佳传达时，或双面板的视觉复杂性会削弱主要信息时。

## 脚本指导

- **开场（0:00 - 0:03）**：立即建立对比。使用并排对比（例如旧 vs. 新、主张 vs. 证明）。
- **中间（0:18 - 0:18）**：使用双面板演示来比较使用场景或质地。确保至少一个片段显示两侧相同动作，以提供公平对比。
- **结尾（0:18 - 0:25）**：将分屏面板合并为单一产品主画面。

## 结尾限制

- 不要使用平台特定的行动号召短语（例如“立即点击”、“上滑”、“简介中的链接”）。
- 结尾应聚焦于品牌、产品或情感信息。
- 可接受的结尾包括：品牌标语、产品展示、美感镜头或利益回顾。

## 示例

- **对比揭示**：左右分屏。左侧面板展示常见痛点；右侧面板从特写角度展示产品解决相同动作。
- **同步演示**：双面板，一个展示完整生活方式动作，另一个突出显示具体机制或质地。
- **合并**：分屏面板过渡为单一画面，以产品干净的主镜头结束。
',
  source='official', sort_order=10, cover_url=NULL, skill_code='cn10', version=0, is_delete=0, gmt_modified=NOW() WHERE id=9;
UPDATE skill SET name='Lookbook Product Ad', description='用于设计时尚型产品画册视频广告，以单一模特在多个场景中展示同一产品，突出其多场景适用性。适用于注重造型的服装、配饰及美妆类画册。不适用于缺乏“一衣多穿”多场景叙事的通用产品演示。', content='---
name: custom-ecom-lookbook
description: 用于设计时尚型产品画册视频广告，以单一模特在多个场景中展示同一产品，突出其多场景适用性。适用于注重造型的服装、配饰及美妆类画册。不适用于缺乏“一衣多穿”多场景叙事的通用产品演示。
