## 操作指南

- 将此格式作为电商产品视频的内容类型指导。
- 按定义的时间分段结构编写脚本。
- 在轮换背景、姿势和氛围时，保持产品持续可见。
- 确保每个场景段落服务于特定使用场景（例如工作日、周末、旅行）。
- 在开头0.5-3秒内使用转场钩子，突出多场景适用性的卖点。

## 适用场景

- **适用场景**：服装、鞋履、配饰或基于造型的美妆产品。需要“单一模特，多场景”结构来展示搭配范围的项目。
- **不适用场景**：非可穿戴/可搭配产品、缺乏场景变换叙事的标准功能导向产品广告，或需要平台特定行动号召按钮的视频。

## 工作流程

1. **开场（0:00-0:03）**：以转场或揭示画面开场，突出产品的多场景适用性。
2. **中段（0:03-0:18）**：展示3-5个场景变化。混合使用全景（场景环境）、中景（氛围变化）和特写（产品/面料质感）。
3. **结尾（0:18-0:25）**：以品牌或产品主导的收尾结束。总结产品的多场景适用性。

## 输出要求

- 每个片段需包含镜头类型、画面动作及音频/文字轨道。
- **结尾限制**：不得使用直接行动号召短语（例如“立即购买”、“上滑”、“简介链接”）。聚焦品牌主导或愿景式标语。可接受：品牌标志、产品名称或利益点标语。

## 示例

- **开场**：模特从不完整造型切换至完整着装。文字：“一件单品，三种风格。”
- **中段**：城市环境全景。文字：“都市通勤。”随后生活方式中景。文字：“周末随性。”
- **结尾**：最终主角镜头。画外音：“适配你一天的每一面。”
',
  source='official', sort_order=11, cover_url=NULL, skill_code='cn11', version=0, is_delete=0, gmt_modified=NOW() WHERE id=10;
UPDATE skill SET name='Interview Product Ad', description='用于以采访风格（如街头采访或播客讨论）编写电商产品视频脚本。当目标是通过对话式社交证明和多说话者节奏来呈现产品优势时使用。不适用于直接响应式销售宣传、单人独白或需要多平台行动号召的视频。', content='---
name: custom-ecom-interview
description: 用于以采访风格（如街头采访或播客讨论）编写电商产品视频脚本。当目标是通过对话式社交证明和多说话者节奏来呈现产品优势时使用。不适用于直接响应式销售宣传、单人独白或需要多平台行动号召的视频。
version: 0.1.0
---

## 说明

- 选择一种采访子格式（例如，街头采访、播客）。
- 将脚本按时间分段：开场（0:00-0:03）、中间（0:03-0:18）和结尾（0:18-0:25）。
- 为每位嘉宾的陈述配上一个描述性注释，用于后续镜头中的产品视觉切换或演示。
- 遵循此脚本格式：为每个片段标明镜头类型、画面动作以及音频/文字轨道。
- 保持说话者轮次简洁，以维持观众参与度。
- 确保参与者和幽默元素严格与产品洞察相关。

## 使用时机

- 适用：街头采访、播客式对话、会议小组讨论或多人物讨论形式。
- 适用：当产品优势最适合通过提问、反应和对话式社交证明来传达时。
- 不适用：单人独白、直接面对镜头的销售宣传或需要复杂多平台行动号召的视频。

## 工作流程

1. 定义采访子格式。
2. 使用一个建立商业紧张感的问题来起草开场钩子（0-3秒）。
3. 使用问答-切换的节奏来开发中间部分（3-18秒）。
4. 使用品牌主导、产品主导或情感主导的内容来设计结尾（18-25秒）。

## 输出要求

- 避免直接响应式行动号召短语（例如，“点击链接”、“立即购买”、“向上滑动”）。
- 将结尾聚焦于品牌/产品身份，例如标语、最终产品美图或优势总结。

## 示例

- 开场：采访者问：“你日常中最浪费时间的是什么？”（双人镜头）。
- 中间：嘉宾手持产品回答；脚本注明一个展示产品使用的切换镜头（特写/切换镜头）。
- 结尾：品牌标语 + 产品的最终主镜头（主镜头）。
',
