UPDATE skill SET name='Product Display Ad', description='提供创建以产品为中心、无人物出镜的电商视频指南，采用渐进式细节展示结构。适用于强调材质、机制和功能的产品详情页或教育类内容。不适用于以模特或人脸为主的生活化视频。', content='---
name: custom-ecom-product-display
description: 提供创建以产品为中心、无人物出镜的电商视频指南，采用渐进式细节展示结构。适用于强调材质、机制和功能的产品详情页或教育类内容。不适用于以模特或人脸为主的生活化视频。
version: 0.1.0
---

## 操作指南

- 遵循定义的渐进式展示结构：轮廓、宏观纹理、功能机制、最终产品特写。
- 保持严格的无人物出镜视觉风格；仅在产品演示时可使用手部动作。
- 屏幕文字使用简洁的功能标签，避免完整句子。

## 适用场景

### 适用场景
- 创建仅展示产品或细节优先的视频内容。
- 演示技术规格、材质、表面处理或包装。
- 提升产品在电商平台或产品教育页面的可见性。

### 不适用场景
- 以真人演员或人脸为主的生活化广告。
- 需要通过人际互动进行叙事的故事型视频。
- 依赖社交证明或网红推荐的内容。

## 工作流程

### 脚本结构
- **开场（0:00–0:03）：** 通过机械动作、材质运动或比例展示揭示产品主要特征。避免通用的产品旋转展示。
- **中段（0:03–0:18）：** 按重要性从高到低排列功能特征，提供产品执行功能时的微距镜头。
- **结尾（0:18–0:25）：** 以居中产品特写、品牌标识组合或简洁的卖点标语收尾。

## 输出要求

### 创意限制
- **灯光与镜头：** 使用受控的洁净灯光和稳定镜头运动（如旋转台、微距平移）。
- **人物元素：** 排除人脸和分散注意力的背景道具。
- **结尾内容：** 仅聚焦品牌或产品主导的信息。不包含平台操作型行动号召。

### 脚本格式
- 按时间长度分段脚本。
- 定义每个镜头的：镜头类型、屏幕动作、对应的画外音或屏幕文字。
',
  source='official', sort_order=15, cover_url=NULL, skill_code='cn15', version=0, is_delete=0, gmt_modified=NOW() WHERE id=14;
UPDATE skill SET name='Close Up Product Ad', description='用于创建聚焦于微距视觉、纹理及特定真实使用场景的电商产品视频脚本。当需要通过特写镜头突出产品实用性时触发此脚本。', content='---
name: custom-ecom-closeup
description: 用于创建聚焦于微距视觉、纹理及特定真实使用场景的电商产品视频脚本。当需要通过特写镜头突出产品实用性时触发此脚本。
version: 0.1.0
---

## 指令

- 将脚本分为三个时间分段：开场（0:00-0:03）、中段（0:03-0:18）和结尾（0:18-0:25）。
- 为每个分段定义：镜头类型、画面动作、以及对应的对话或屏幕文字。
- 明确将每个微距或特写镜头与真实物理条件（如压力、湿度、纹理、抓握力或日常磨损）相关联。
- 优先展示产品在受力状态下的表现镜头，而非抽象的美学镜头。
- 谨慎使用屏幕文字标注，仅用于标识物理条件及由此产生的用户利益。

## 使用时机

### 适用场景
- 通过可见纹理、机制、使用方法或精确贴合来突出产品价值时。
- 在特定物理环境中展示产品耐用性或实用性时。
- 需要以亲密感和细节作为产品质量证明的内容创作时。

### 不适用场景
- 缺乏对特定产品属性关注的通用品牌认知活动。
- 主要依赖广角镜头或电影级景观的内容。
- 需要平台特定行动号召按钮、导航提示或外部链接指令的场景。

## 输出要求

### 脚本结构
- **开场（0:00-0:03）：** 先展示物理条件，再揭示解决该问题的产品特性，以此建立好奇心缺口。
- **中段（0:03-0:18）：** 按顺序排列特写镜头，展示产品在至少两种不同真实生活条件下的表现。
- **结尾（0:18-0:25）：** 提供以品牌或产品为主导的结论。不得包含“立即点击”、“立即购买”或点击外部链接的指令。

## 示例

**场景：** 防水登山靴
- **开场：** 水珠在织物表面凝结的微距镜头。画外音：“自然条件不会等你的靴子晾干。”
- **中段：** 鞋底在压力下抓握湿滑岩石表面的特写镜头。
- **结尾：** 靴子在小径上的宽景细节镜头。画外音：“为你的选择而造。”
