片段 1：T3 仪表盘对话——两个角色争论小费问题
片段 2：T2 章节卡——红色背景上的“金发先生”
片段 3：T6 配乐行走——一群穿黑西装的人慢动作行走
片段 4：T5 墨西哥对峙——三把枪指着，摄影机环绕
```

