```
片段 1：T4 恋物癖特写——赤脚踩上木地板
片段 2：T8 急推变焦——快速切到目标的脸（认出）
片段 3：T6 配乐行走——新娘向前走，慢动作
片段 4：T10 长镜头对话——面对面，暴力前的沉默
```

