### “时间错乱刺杀”
```
片段 1：T10 长镜头对话——谈判（之后）
片段 2：T2 章节卡——“4 小时前”
片段 3：T6 配乐行走——到达地点（之前）
片段 4：T5 墨西哥对峙——对峙（期间）
