## 反模式（切勿这样做）

- 切勿将塔伦蒂诺技巧用于健康/可爱内容（错误的工具箱）
- 切勿在没有角色向下看的情况下进行后备箱镜头（这才是重点）
- 切勿仓促进行墨西哥对峙（紧张需要时间）
- 切勿在每个序列中使用超过一次急推变焦（会失去冲击力）
- 切勿选择与时代/角色不匹配的配乐歌曲
- 切勿通过过快剪辑使对话场景变得无聊（保持镜头）
- 切勿忘记塔伦蒂诺的暴力有后果和幽默
- 切勿在没有叙事目的的情况下使用分屏（它不是装饰）
- 切勿让章节卡字体无聊（字体就是个性）
- 切勿在没有视觉区分的情况下使用时间跳跃（观众必须知道）
- 反油腻：塔伦蒂诺的风格大胆但绝不空洞——每种技巧都为角色或紧张服务
- 音乐不是背景——音乐就是场景

---

## 规则

- 每种技巧必须服务于角色或紧张（说明目的）
- 音乐/声音设计对塔伦蒂诺来说是强制性的——除非沉默本身就是紧张，否则永远不要静音
- 调色板：温暖的金色、深红色、刺眼的荧光灯、70 年代模拟感
- 建议使用胶片颗粒以获得符合时代的感觉
- 急推变焦：每个序列最多一次
- 反油腻：酷服务于角色，暴力服务于故事，风格服务于实质
