5. 分析第一个“目标背景图像”中人的状态，例如“站立”、“坐着”或“躺着”，并将结果填写到**“提示”**中的[目标动作]位置。
6. 如果目标人物来自图像，在确定第一个“目标背��图像”中人物的可见区域与第二个“目标人物图像”中人物的可见区域是否匹配之前，必须调用analyze_canvas_nodes或使用子代理检查两个图像。仅当视觉分析确认“目标人物图像”的可见区域大于“目标背景图像”时，才在提示中适当的位置插入【裁剪掉人物多余的部分】。如果目标人物来自文字描述，则根据目标背景图像的可见区域生成目标人物，并且不与第二图像进行比较。7. 如果目标人物来自图像，并且analyze_canvas_nodes或子代理目视确认“目标背景图像”的可见区域大于“目标人物图像”，则分析哪些身体部位出现在“目标背景图像”中但在“目标人物图像”中缺失，并将这些额外部分应该穿的衣服添加到[人物描述]部分，例如“灰色裤子”，“裙子”或“鞋子”。添加的描述应根据实际性别等上下文进行推断，不应直接描述图1所示的服装。如果目标人物来自文字描述，则根据目标背景图像的可见区域和目标人物文字描述完成合理的服装。
8、如果目标人物来自图像，则分析目标人物图像中人物的服装和皮肤材质，并填写到**“提示”**中的【材质描述】位置。使用“皮肤具有哑光质感”。如果目标人物来自文字描述，则根据文字描述填写【材质描述】，保留“皮肤有磨砂质感”。
9. 分析第一张“目标背景图”中的景深，例如“特写”、“近景”、“中景”或“远景”，并将结果填充到**“提示”**中的【景深和拍摄角度】位置。10. 在确定第一个“目标背景图像”中脚和鞋子是否可见之前，必须调用analyze_canvas_nodes或使用子代理检查图像。不要仅从可见区域标签推断这一点。只有当目视分析清楚确认双脚和鞋子都可见时，才在**“提示”**中的[目标动作]位置后插入[双脚都站在地面上，]。如果脚或鞋子不可见、被遮挡、被裁剪或不确定，请勿插入此内容。
