## AI视频生成负面提示词库

使用这些负面提示词来防止常见的AI视频伪影。将相关条目附加到任何提示模板中。

### 通用负面提示词（每次生成都包含）

```
负面提示词：面部变形、五官融化、多余手指、多余肢体、畸形的手、模糊的脸、斗鸡眼、不对称瞳孔、牙齿伪影、头发与背景融合、场景突变、画面跳跃、时间闪烁、帧间光照不一致、衣物纹理流动、皮肤纹理爬行、背景扭曲、地板滑动、墙壁呼吸、镜头中透视变化、物体出现或消失、阴影方向变化、色带、压缩伪影、水印、文字叠加、分屏伪影、重复主体、镜像加倍、宽高比失真
```

### 镜头运动特定负面提示词

```
镜头运动负面提示词：卡顿运动、急停摇镜、速度不一致、橡皮筋式回弹、镜头位置瞬移、不可能的透视变化、令人眩晕的旋转、运动期间帧率下降、错误轴向上的动态模糊、视差错误、变焦步进而非平滑、环绕轴摆动、升降机抖动、轨道车颠簸可见、锁定镜头时的手持晃动、画面边缘的稳定变形
```

### 角色和面部特定负面提示词

```
角色负面提示词：表情间面部变形、眼睛颜色变化、肤色变化、发色不一致、剪辑间服装变化、身体比例变化、身高变化、场景内年龄变化、妆容出现或消失、配饰瞬移、珠宝穿透皮肤、领口和领线变形、耳朵形状变化、鼻梁扭曲、口型同步伪影、下巴脱臼、脖子拉长、肩膀宽度波动
```

### 照明与色彩特定负面提示

```
照明负面提示：光源位置跳跃、阴影方向反转、色温闪烁、曝光脉动、高光裁切振荡、镜头光晕忽隐忽现、表面反射不一致、镜面高光游移、环境光水平跳跃、正午场景出现黄金时刻光、指定暖色场景出现冷光、多个冲突的阴影方向、指定戏剧性时出现平光、指定平光时出现戏剧性光
```

### 环境与背景负面提示

```
环境负面提示：背景视差错误、远处物体移动过快、树木和 foliage 突然出现或消失、天空颜色变化、云朵瞬移、水面伪影、地板纹理游移、墙壁纹理爬行、建筑元素扭曲、门和窗户形状变化、家具位置移动、道具连续性错误、反射表面不一致、地面倾斜、地平线移动、景深雾效不一致
```

