# 品牌设计系统

## 品牌设计师理念

这不是一个设计模板库。这是**品牌策略师的大脑**。

模板上写着：“这里有 50 个调色板，请选择一个。”
一位品牌设计师说：“这个品牌代表什么？受众是谁？人们遇到它时应该有什么感觉？是什么让它与众不同？然后——只有到那时——视觉系统是什么样子？”

该系统按以下顺序思考：
1. **为什么**先于什么（品牌策略先于视觉决策）
2. **FEEL** before STYLE（审美选择之前的情感反应）
3. **SYSTEM** 在 ELEMENT 之前（单个资产之前的一致性标识）

每一个视觉决策都传达了：品牌相信什么、为谁服务、与竞争对手有何不同以及它的发展方向——所有这些都没有任何文案。

---

## 品牌设计师的工作流程（如何使用该系统）

不要跳到颜色和字体。像品牌设计师一样思考：

### 第一阶段：品牌战略（模块 1-2）
1. **定义品牌定位**（模块1）->建立战略基础
2. **建立品牌个性**（模块 2）-> 定义声音、语气和性格

### 第 2 阶段：核心视觉识别（模块 3-5）
3. **设计标志系统**（模块3）->品牌的视觉锚点
4. **构建色彩系统**（模块 4）-> 情感和功能色彩架构
5. **选择排版系统**（模块5）->将言语个性视觉化

### 第 3 阶段：扩展视觉语言（模块 6-8）
6. **创建视觉元素和图案**（模块 6）-> 可拥有的图形设备
7. **建立布局和网格系统**（模块7）->结构一致性
8. **定义摄影和图像风格**（模块 8）-> 视觉叙事标准

### 第 4 阶段：应用与演进（模块 9-13）
9. **指定品牌应用**（模块9）->现实世界的实施规则
10. **设计动作和动画**（模块 10）-> 动态品牌表达
11. **构建数字品牌系统**（模块11）-> UI/UX品牌整合
12. **进行品牌审核和发展**（模块 12）-> 衡量和发展
13. **生成完整的品牌手册**（模块 13）-> 为什么 -> 做什么 -> 如何公式

自由组合模块。 “具有远见个性 (M2) 的高端科技品牌 (M1)，使用深海军蓝几何文字标记 (M3) + 电蓝色 (M4) 和单色怪诞字体 (M5)”为您提供精确、分层的品牌标识。

---

## 模块 1：品牌战略与定位——战略基础

在做出任何视觉决策之前，先定义品牌是什么。策略是每个视觉元素都必须服务的隐形架构。没有它，设计就是装饰。

### 1.1 挑战者品牌

**它传达的信息：** 颠覆、大胆、拒绝接受现状。这个品牌的存在是为了推翻品类领导者。

**策略规则：**
- 定位：对抗主导者——通过你拒绝的东西来定义你自己
- 语气：自信、挑衅、略带攻击性、从不道歉
- 视觉方向：刻意打破类别惯例
- 空间：主张领导者忽视或服务不足的领土

**品牌战略框架：**
````
品牌定位：挑战者/颠覆者
类别：[行业]
敌人：[主导玩家/拒绝约定]
核心信念：【品牌为何而战】
观众：[谁对现状感到沮丧]
证明点：[为什么这个品牌可以做到]

视觉方向：大胆的不对称构图、高对比度、非常规的颜色、打破规则的排版、锐利的棱角图形元素。视觉系统应该感觉像一份宣言——紧急、毫无歉意、无法忽视。
````

**AI图像提示——挑战者品牌英雄视觉：**
````
挑战者[工业]公司的大胆挑衅的品牌视觉。戏剧性的高对比度构图，锐利的对角线穿过画面。调色板故意打破[行业]惯例——[非常规颜色]在竞争对手使用[常规颜色]的地方占主导地位。排版前卫的设计采用超大粗体无衬线字体创造建筑结构。不对称布局，元素之间有意产生张力。原始的工业纹理与精确的几何形状混合在一起。深色戏剧性背景与单一大胆的强调色创造视觉冲击力。该设计散发出自信和对类别规范的反叛。工作室品质的品牌摄影风格、编辑时尚灯光、4K、干净锐利的边缘、优质的打印质量。
````

### 1.2 权威品牌

**它传达的信息是：** 专业知识、信任、良好的业绩记录。该品牌凭借知识和信誉而领先。

**策略规则：**
- 定位：权威专家——他人参考
- 语气：谨慎、自信、基于证据、绝不华而不实
- 视觉方向：经典比例、宽敞的留白、内敛的调色板
- 空间：拥有该品类的“黄金标准”地位

**品牌战略框架：**
````
品牌定位：权威/专家领袖
类别：[行业]
专业领域：[特定知识领域]
核心信念：【指导决策的原则】
观众：[谁需要值得信赖的专业知识]
凭证：[权威证明]

视觉方向：古典比例、慷慨的空白、内敛的调色板（海军蓝、炭灰色、白色、一种柔和的口音）、衬线或精致的无衬线字体、对称的构图、传达精确性的最小图形元素。视觉系统应该感觉像一个值得信赖的机构——冷静、确定、超越潮流。
````

**AI图像提示——权威品牌英雄视觉：**
````
领先的[行业]公司的精致权威品牌视觉。简洁的构图，大量的空白和经典的黄金比例。深海军蓝、温暖的炭灰色、清爽的白色等内敛的调色板，以及少量使用的单一柔和的[强调色]。精致的衬线字体，具有完美的字母间距和优雅的粗细对比。对称平衡布局暗示稳定性和秩序。微妙的纹理细节——细亚麻纸纹理或压花表面质量。每个元素放置的建筑精度。左上方柔和的定向照明营造出柔和的空间感。没有装饰元素——每个组件都有其用途。该设计散发着平静的信心和机构信任。 4K、优质印刷制作质量、平版印刷美学。
````

### 1.3 创新者品牌

**它传达的信息：** 前瞻性思维、技术驱动、建设未来。这个品牌总是领先一步。

**策略规则：**
- 定位：先锋——率先进入市场、率先想象
- 语气：乐观、好奇、技术性但平易近人、有远见
- 视觉方向：干净的极简主义、动态元素、技术前沿的调色板
- 空间：拥有品类的“未来”

**品牌战略框架：**
````
品牌定位：创新者/先锋
类别：[行业]
创新论文：【品牌正在打造什么样的未来】
核心信念：【为何现状不足】
观众：[早期采用者和前瞻性思考者]
技术：[赋能能力]

视觉方向：超干净的极简主义，带有动态口音、渐变或发光颜色处理、几何无衬线字体、宽敞的负空间、微妙的运动暗示元素（渐变、粒子、光迹）。视觉系统应该感觉像是未来的原型——精确、明亮、毫不费力地先进。
````

**AI图像提示——创新者品牌英雄视觉：**
````
一家先锋[工业]公司的未来创新品牌视觉。超干净的最小构图与巨大的负空间。调色板具有从 [COLOR A] 到 [COLOR B] 过渡的发光渐变，暗示能量和前进的动力。时尚的几何无衬线字体，具有精确的数学字母间距。微妙的光迹效果和柔软的粒子系统创造出深度而不混乱。纯深黑色或原始白色背景，带有浮动半透明几何形状。全息或棱镜光强调捕捉干净 3D 形状的边缘。一切都感觉轻盈、精确，并且略微领先于当前的设计趋势。柔和的环境照明，没有刺眼的阴影。该设计散发着智能简约和技术乐观的气息。 4K、CGI 产品渲染质量、Apple 级设计精致。
````

### 1.4 传统品牌

**它传达的信息：** 传统、工艺、经过时间考验的品质。该品牌通过数十年的卓越表现赢得了自己的地位。

**策略规则：**
- 定位：原创——真实、既定、不可替代
- 语气：端庄、温暖、富有传奇色彩，从不渴望关注
- 视觉方向：丰富的材质、复古风格的调色板、经典的排版
- 空间：拥有“正宗”和“原创”的地位

**品牌战略框架：**
````
品牌定位：传承/传承
类别：[行业]
起源故事：[创始叙事]
核心信念：【永恒的原则】
观众：[谁重视真实性和工艺]
遗产证明：[年份/成就/遗产]

视觉方向：丰富的暖色调（酒红色、森林绿、海军蓝、金色、奶油色）、带有历史参考的衬线排版、少量使用的装饰细节、天然材料纹理（皮革、纸张、木纹）、纹章或波峰影响的图形元素。视觉系统应该感觉像是一件传家宝——珍贵、传奇、经久不衰。
````

**AI图像提示——传承品牌英雄视觉：**
````
一家拥有 [YEARS] 年历史的老牌 [工业] 公司，拥有丰富的传统品牌视觉效果。温暖奢华的组合，具有深邃丰富的色彩——酒红色、森林绿、复古金色和温暖的奶油色。经典的衬线字体，精致的细节和大方的比例，暗示着手工设置的凸版印刷品质。边缘处有微妙的装饰边框或金丝细节，内敛而优雅。天然材料纹理清晰可见——做旧皮革纹理、细棉纸纤维、带有阴影深度的微妙压花。中心对称构图与纹章平衡。温暖的定向照明暗示午后阳光透过旧窗户。柔和的色彩等级，具有丰富的阴影和温暖的高光。一切都暗示着持久性、工艺性和对经过验证的品质的信心。 4K、复古编辑摄影品质、名利场美学。
````

### 1.5 生活方式品牌

**它传达的信息：** 愿望、归属感、身份表达。这个品牌是一个徽章——拥有它就说明了你是谁。

**策略规则：**
- 定位：身份标记——你就是你的选择
- 基调：有抱负、包容但排他性、文化意识、情感共鸣
- 视觉方向：以摄影为主导，温暖的人性时刻，精心策划的美学
- 空间：拥有一种感觉，而不是一个特征

**品牌战略框架：**
````
品牌定位：生活方式/身份
类别：[行业]
文化领域：[生活方式/亚文化/愿望]
核心信念：【品牌代表什么生活哲学】
观众：[谁认同这种生活方式]
徽章价值：[拥有这个品牌说明了您的什么]

视觉方向：以摄影为主导，精心策划的编辑质量，温暖的自然主义调色板，干净的现代无衬线字体，不与图像竞争，宽敞的呼吸空间，产品镜头上的生活方式瞬间。视觉系统应该像一本你想住在里面的杂志——充满抱负、温暖、轻松的酷感。
````

**AI图像提示——生活方式品牌英雄视觉：**
````
一家[行业]公司的理想生活方式品牌视觉。社论摄影前向构图展示了自然美丽的[环境]中的[主体/人物]，捕捉到了真实的不摆姿势的时刻。温暖的黄金时刻灯光，自然又迷人。温暖的大地色调、柔和的白色和自然绿色的调色板与一种[品牌颜色]口音有机地出现在场景中。干净的现代无衬线字体覆盖着宽大的间距��小而优雅，不与图像竞争。浅景深聚焦于人类瞬间。胶片颗粒纹理暗示着模拟温暖——柯达 Portra 400 美学。该图像讲述了一个关于生活方式的故事，而不是关于产品的故事。 4K、编辑生活摄影品质、Kinfolk 杂志审美。
````

### 1.6 高级/奢侈品牌

**它传达的信息是：** 独特、卓越的品质、精致的品味。这个品牌适合少数人，而不是大多数人。

**策略规则：**
- 定位：专属选择——稀缺即价值
- 语气：低调、精确、从不大声、显得成熟
- 视觉方向：最大限度的克制、珍贵的材料、完美的执行
- 空间：拥有“最好”的位置——而不是“最”的位置

**品牌战略框架：**
````
品牌定位： 高级/豪华
类别：[行业]
排他性驱动因素：[是什么使它稀有或特殊]
核心信念：【它所坚持的卓越标准是什么】
观众：【认可品质的挑剔消费者】
价格理由：[工艺/材料/遗产/经验]

视觉方向：最大限度的克制——更少的元素，每一个都完美无缺。黑色、白色、金色、深宝石色调。高对比度排版和极端字母间距。巨大的负空间本身就是一种奢侈。材质质感暗示着触感——烫金、压花、厚重的原料。视觉系统应该让人感觉需要花钱才能生产——因为确实如此。
````

**AI图像提示——优质品牌英雄视觉：**
````
独家[行业]公司的超高端奢侈品牌视觉效果。极其简约的构图，带有 70% 的负空间，呈深哑光黑色或原始白色。精致的细长无衬线字体，具有戏剧性的字母间距（200-300% 跟踪），通过克制暗示排他性。单一珍贵的点缀 - 一条细线的真金箔闪闪发光，或在精确控制的区域出现深宝石色调[颜色]。表面纹理暗示着物理奢华——触感柔软的哑光涂层、印刷上微妙的斑点紫外线光泽、产生阴影的深盲压纹。完美的对称性。没有任何装饰——每个元素都合理。柔和的单源照明在哑光表面上营造出柔和的渐变效果。设计通过它所保留的内容而不是它所展示的内容来传达信息。 4K，奢华包装摄影品质，Hermes/Celine级别的克制。
````

### 1.7 社区品牌

**它传达的信息：** 归属感、共同价值观、集体力量。这个品牌是一种运动，而不是一种产品。

**策略规则：**
- 定位：聚集点——我们，不是我
- 语气：包容、充满活力、赋权、参与
- 视觉方向：温暖、多元、以人为本、适应性强的标识系统
- 空间：拥有“在一起”的位置

**品牌战略框架：**
````
品牌定位：社区/运动
类别：[行业]
共同的事业：[是什么让社区团结起来]
核心信念：【集体行动为何重要】
观众：[想要归属并做出贡献的人]
参与模型：[人们如何加入和参与]

视觉方向：温暖而充满活力的调色板，具有代表多样性的多种强调色，友好的圆形排版，适应社区贡献的灵活的身份系统，在真实时刻呈现真实不同的人的摄影，暗示人性化的手绘或有机图形元素。视觉系统应该给人一种邀请的感觉——开放、温暖、充满活力。
````

**AI图像提示——社区品牌英雄视觉：**
````
一家[行业]公司的温暖包容的社区品牌视觉。充满活力的多色构图，多种暖色调——珊瑚色、琥珀色、天蓝色、鲜绿色、暖紫色——和谐共存。友好的圆形无衬线字体，具有舒适的重量和宽敞的比例，感觉平易近人且人性化。有机手绘图形元素——不完美的圆圈、流畅的线条、自然的形状——与干净的设计结构混合在一起。温暖的灰白色或软奶油背景。摄影元素与图形元素相结合，展示了不同的真实人物在真实的联系时刻。俏皮的不对称布局与有意的视觉节奏。一切都感觉手工制作又专业，组织有序又有机。温暖均匀的灯光，没有刺眼的阴影。 4K，社区品牌摄影品质，温暖的编辑审美。
````

### 1.8 极简主义品牌

**它传达的信息：** 清晰、诚实、本质主义。这个品牌去掉了一切不必要的东西，以揭示重要的东西。

**策略规则：**
- 定位：必要的选择——少即是多，做得对
- 语气：直接、诚实、干净、绝不装饰
- 视觉方向：彻底还原、功能美感、系统精准
- 空间：将自己的“简单性”作为竞争优势

**品牌战略框架：**
````
品牌定位：极简/精要
类别：[行业]
它消除了什么：[消除复杂性/噪音/浪费]
核心信念：【简单为何优越】
观众：[谁重视清晰度和功能]
简化证明：[是什么让简单变得真实，而不是懒惰]

视觉方向：单色或非常有限的调色板（最多 2-3 种颜色）、具有数学精度的几何无衬线字体、极端负空间、无装饰元素、具有可见结构的基于网格的构图、形式服从功能的功能美。视觉系统应该感觉像包豪斯练习——每个元素都通过功能证明合理，从逻辑中产生美感。
````

**AI图像提示——极简品牌英雄视觉：**
````
一家[行业]公司的超简约本质主义品牌视觉。纯白色的构图，80% 的负空间。单色调色板——纯白色背景上的纯黑色元素，在一个位置使用一种精确的[颜色]重音。几何无衬线字体，具有数学上精确的比例和间距，Helvetica Neue 或 Akkurat 质量。单一几何形状或形式作为唯一的图形元素，根据网格逻辑完美放置。无纹理、无渐变、无阴影——纯粹的平面图形精度。设计下方几乎可见网格线，结构逻辑显而易见。每个元素都以像素完美的意图定位。该设计通过彻底的减少来实现美感。 4K、瑞士图形设计品质、Josef Muller-Brockmann 精度。
````

---

## 模块 2：品牌个性与声音——设计背后的性格

每个品牌都是一个角色。在选择颜色或字体之前，先定义品牌是谁。该模块将个性特征转化为具体的视觉和语言设计决策。

### 2.1 有远见的人

**它传达的信息：** 大局思考、灵感、未来导向。这个品牌看到了别人看不到的东西，并且充满信心。

**性格特征：** 富有想象力、大胆、理想主义、鼓舞人心、略显激烈
**语音：** 陈述性陈述、将来时、简单陈述的大想法

**视觉翻译：**
- 颜色：深空调色板（海军蓝、黑色、白色），带有夜光色调（电蓝色、紫色）
- 版式：干净的几何无衬线、中等粗细、宽大的跟踪——视觉清晰
- 图像：广阔的风景、地平线、空间、突破的光线、令人谦卑的规模
- 图形元素：延伸至无限的简洁线条、最小的几何形状、光线
- 布局：宽敞的负空间——品牌不会填满每个角落，它会呼吸

````
有远见的品牌个性视觉。广阔的构图在无限的地平线或深空背景下展示了[主题]。深午夜海军蓝色调过渡到明亮的电蓝色，并带有精确的白色点缀。干净的几何无衬线字体漂浮在空间中，具有宽敞的跟踪和呼吸空间。干净的白光射线从消失点产生定向能量。尺度对比——微小的精确的人类元素与巨大的宇宙或景观尺度的对比。气氛清晰、目标明确。没有杂乱，没有装饰。The composition looks forward and upward.画面内的电影宽银幕比例、电影品质的灯光和镜头光晕强调。 4K, Interstellar movie poster quality.
````

### 2.2 工匠

**它传达的信息：** 注重细节，对过程感到自豪，质量重于数量。这个品牌非常关心产品的制造方式。

**性格特征：** 细致、耐心、骄傲、热情、注重细节
**声音：** 以流程为中心，具体，有触觉的语言，自豪而不傲慢

**视觉翻译：**
- 颜色：温暖的自然色调（原皮、陈年木材、奶油色、暖灰色、铜色）
- 排版：人文主义衬线或精致的无衬线，细节可见工艺
- 图像：特写纹理、工作中的双手、原材料、工具、过程时刻
- 图形元素：精细的线条、微妙的扭索图案、手绘品质
- 布局：考虑间距，明显注意对齐和比例

````
工匠品牌个性视觉。亲密的特写构图展示了具有非凡纹理细节的[工艺细节/材料/工具]。温暖的自然色调——原皮棕色、陈年橡木、暖铜色、柔和的奶油色、木炭色。来自车间窗户的自然定向照明，温暖的 3200K 色温，创造出丰富的阴影，揭示表面纹理。每一个纹理、针脚和瑕疵都清晰可见、美丽动人。人文主义衬线字体，精致的细节暗示着手工切割的字体。天然材料背景 — 木质工作台、亚麻布、原料金属。浅景深将人们的注意力吸引到工艺上。灰尘颗粒捕捉光线。该图像颂扬了过程、耐心和手工制作的品质之美。 4K、静物摄影品质、Kinfolk/Cereal 杂志审美。
````

### 2.3 反叛者

**它传达的信息：** 反抗、真实、反文化能量。这个品牌存在于主流之外是自愿的。

**性格特征：** 大胆、原始、真实、挑衅、不妥协
**声音：** 直接、白话、有时粗俗、总是诚实、反企业

**视觉翻译：**
- 颜色：高对比度与原始能量（黑色 + 热红色、黑色 + 霓虹灯、带有震撼效果的单色）
- 排版：混合风格——做旧、手写、故意不完美、反设计
- 图像：街头摄影、未经修饰的原始瞬间、粗糙的纹理、亚文化
- 图形元素：撕裂边缘、喷漆痕迹、复印工件、拼贴美学
- 布局：故意破坏网格、重叠元素、隐藏秩序的视觉混乱

````
叛逆品牌个性视觉。原始的高能量成分，带有刻意的反设计美学。鲜明的黑白底色，带有侵略性的[强调色——火红/霓虹绿/电黄色]横穿框架。混合排版——仿旧的手写形式与干净的工业风格相冲突，不同的尺寸和角度创造了视觉张力。纸张边缘撕裂、复印伪影、半色调点图案可见。坚韧的混凝土或沥青纹理作为背景。街头摄影品质——闪光灯、高光轻微曝光、深沉的黑色。喷漆标记和滴水纹理作为图形元素。重叠的层次创造了深度和受控的混乱。该设计看起来像是紧急制作的，充满信心，零企业打磨。 4K但刻意原始，杂志文化审美，朋克摇滚视觉语言。
````

### 2.4 养育者

**它传达的信息：** 关怀、安全、温暖、情感支持。这个品牌让人们感到受到保护和理解。

**性格特征：** 热情、善解人意、温柔、可靠、情商高
**声音：** 柔和、支持性、第二人称、温暖、令人安心

**视觉翻译：**
- 颜色：柔和的暖色调（腮红粉、鼠尾草绿、暖奶油色、柔和的桃色、柔和的薰衣草色）
- 版式：圆角友好的无衬线或柔和的人文主义衬线，中等重量，舒适
- 图像：柔和的自然光、人性化的时刻、柔和的纹理、舒适的物体
- 图形元素：有机柔和的形状、圆角、流动的曲线、无锐角
- 布局：宽大的填充、柔和的边缘、呼吸空间、居中的构图

````
培育品牌个性视觉。柔软温暖的成分散发着舒适和关怀。柔和柔和的调色板——腮红、鼠尾草绿、温暖的奶油色、柔和的桃色——融入平滑的有机渐变。圆润友好的无衬线字体，具有舒适的重量和宽敞的比例，以充足的呼吸空间为中心。有机斑点形状和流动曲线作为背景元素，任何地方都没有尖角或侵略性角度。柔和的漫射自然光，如清晨透过透明窗帘的阳光��温暖的 3000K 色温。质地柔软的棉质、柔和的亚麻、光滑的陶瓷。一切都圆润、温暖、诱人。构图感觉就像一个温柔的拥抱。 4K，生活摄影温馨，母性舒适唯美。
````

### 2.5 艺人

**它传达的信息：** 快乐、惊喜、有趣、难忘的经历。这个品牌让人们微笑并再次光顾。

**性格特征：** 顽皮、令人惊讶、精力充沛、机智、略带不敬
**声音：** 对话式、出乎意料、双关语、有节奏、令人愉快

**视觉翻译：**
- 颜色：充满活力的饱和调色板与意想不到的组合（橙色+紫色，黄色+粉红色）
- 版式：富有表现力的显示字体、混合粗细、弹跳基线、个性化
- 图像：动态时刻、喜悦的表情、色彩爆炸、意想不到的并置
- 图形元素：五彩纸屑、曲线、弹跳点、卡通形状
- 布局：动态不对称、打破边界的元素、有意控制的混乱

````
艺人品牌个性视觉。高能量、俏皮的构图充满欢乐和惊喜。充满活力的饱和调色板 - [颜色 A] 和 [颜色 B] 以意想不到的大胆组合，加上对比色调的支撑口音。富有表现力的显示排版具有跳跃的基线和混合的重量，字母几乎在跳舞。五彩纸屑、曲线和几何形状随机散落。背景弹出色块和渐变突发。动态对角线构图，元素打破框架边界。光滑的 3D 渲染形状与糖果般的光泽表面俏皮地漂浮。灯光明亮均匀，高调，零影戏。一切都在运转，一切都在庆祝。这个设计让你在读到一个字之前就会微笑。 4K、Nickelodeon 遇见 Figma 品质、纯粹乐观的能量。
````

### 2.6 圣人

**它传达的信息：** 深厚的知识、深思熟虑、学术严谨。这个品牌具有教育意义和启发意义。

**性格特征：** 深思熟虑、善于分析、善于表达、冷静、理智、慷慨
**声音：** 清晰、结构化、基于证据、具有教育意义、绝不居高临下

**视觉翻译：**
- 颜色：柔和的知性调色板（石板蓝、暖灰色、象牙色、柔和的金色、深青色）
- 版式：优雅的衬线，宽大的 x 高度和完美的可读性，学术性
- 图像：抽象概念可视化、数据可视化、结构化信息
- 图形元素：精细规则、系统网格、数学模式、信息层次结构
- 布局：完美的排版网格，内容优先，经典的书籍设计比例

````
圣人品牌个性视觉。充满智慧的优雅构图和学术的精确性。柔和精致的调色板——石板蓝、暖灰色、象牙色，以及用于强调的单一抛光金色。优雅的高对比度衬线字体，具有宽大的 x 高度和完美的字母间距，表明学术出版质量。精细的发际线规则创建了设计下方可见的结构网格。品牌调色板中呈现的数据可视化元素或抽象几何图表，美观且信息丰富。温暖的象牙色或柔软的灰色纸张纹理背景。经典的书籍设计比例，宽边距和仔细的排版层次。一切都井井有条、清晰易读、经过深思熟虑。设计尊重读者的智力。 4K、学术媒体品质、Monocle 杂志美学。
````

---

## 模块 3：标志设计系统——视觉锚点

徽标是任何品牌中最容易识别的元素。它不是品牌本身——而是品牌的签名。一个伟大的标志并不能解释公司的业务；它成为公司给人们带来的感受的代名词。该模块涵盖了所有主要标志类型、构造原理以及用于生成标志概念视觉效果的人工智能提示模板。

### 3.1 文字商标/标识

**它传达的信息：** 对品牌名称本身的信心。文字标记上写着：“我们的名字足够强大，可以独立存在。不需要任何符号。”最适合名称独特、简短、易记的品牌。

**设计规则：**
- 必须使用自定义字体——切勿使用未经修改的字体
- 字母间距（跟踪）定义个性：紧=现代/科技，宽=奢华/时尚
- 字母之间的粗细对比营造出精致感
- 负空间技巧（FedEx 箭头、Toblerone 熊）增加深度而不复杂
- 以最小尺寸进行测试——必须在屏幕上 20 像素宽度下保持清晰

**标志规范框架：**
````
标志类型：文字标志/标志
品牌名称：[品牌名称]
行业：[行业]
性格：[主要特征——大胆/精致/俏皮/严肃]
自定义字体样式：[几何/人文/脚本/黑字]
关键修改：[字母形式的独特之处——自定义连字、修改的终端、集成符号、负空间元素]
重量：[薄/轻/常规/粗/黑色]
跟踪：[紧/正常/宽/超宽]
颜色：[背景]上的[原色]
最小尺寸：[指定像素或毫米]
````

**人工智能图像提示--文字标志概念：**
````
为[行业]公司[品牌名称]设计专业文字标志。 [风格——几何/人文主义/现代衬线]风格的定制手工字体。 [重量] 重量与 [跟踪] 字母间距。 [关键修改——例如，特定字母之间的自定义连字、最后一个字母上的修改终端、隐藏在字母形式中的微妙负空格符号]。干净的矢量质量，纯白色背景上的单色 [颜色]。没有图标，没有符号——只有排版。字体感觉是定制设计的，而不是标准字体。专业的标志设计呈现，居中构图，标志周围留白充足。可打印的矢量质量、平面设计、无渐变、无阴影、无 3D 效果。
````

### 3.2 字母标记/字母组合

**它传达的信息：** 威望、地位、有效的认可。字母标记将长或复杂的名字提炼成令人难忘的首字母缩写。表明该品牌已足够成熟，仅首字母就具有意义。

**设计规则：**
- 字母必须互锁、重叠或几何关联——而不仅仅是并排放置
- 字母之间的负空间创造了设计张力
- 单重笔触感觉现代；可变重量感觉经典
- 考虑堆叠（垂直排列）与水平排列
- 独立测试：每个字母在分开时应保持可识别性

**标志规范框架：**
````
标志类型： 字母/字母组合
首字母缩写：[字母]
全名：[品牌全名]
行业：[行业]
字母关系：[联锁/重叠/堆叠/包含/连字]
笔画风格：[单一粗细/可变/细细]
结构：[几何/书法/建筑]
颜色: [原色]
形状容器：[无/圆形/方形/盾形/自定义]
````

**人工智能图像提示--字母标志概念：**
````
专业字母会标徽标，使用字母 [LETTERS] 代表 [品牌名称]，一家 [行业] 公司。字母 [关系 - 互锁/重叠/堆叠] 具有优雅的几何结构。 [笔画风格] 笔画创建复杂的字母关系。 [容器——包含在一个圆圈内/自由站立]。白色背景上的单色[颜色]。这些字母共享结构元素——��同的笔划、对齐的顶点或互锁的几何形状。感觉像是建筑师设计的。干净的矢量质量，专业的徽标呈现，居中，宽敞的空白。无渐变，无阴影，扁平专业设计。
````

### 3.3 图形标记/品牌符号

**它传达的信息：** 超越语言的普遍认可。图形标记与特定物体、动物或概念产生即时视觉关联。需要大量的品牌资产才能在没有品牌名称的情况下发挥作用。

**设计规则：**
- 简化为基本形式——删除细节，直到含义几乎崩溃，然后停止
- 必须作为单色剪影
- 避免字面表达；找到诗意或抽象的版本
- 符号应该表明公司的业务，而不是描述公司的业务
- 以网站图标大小 (16x16px) 进行测试——必须保持可识别性

**标志规范框架：**
````
标志类型：图形标志/品牌符号
主题：[该符号描述了什么]
品牌名称：[品牌名称]
行业：[行业]
抽象级别：[文字/风格化/高度抽象]
几何结构：[CIRCLE-BASED / GRID-BASED / GOLDEN-RATIO / ORGANIC]
视觉隐喻：[超越文字图像的暗示]
线条质量：[尖锐/圆形/混合]
填充样式：[实体/轮廓/部分填充]
颜色: [原色]
````

**AI图像提示--图形标志概念：**
````
专业图形品牌符号标志，描绘了[品牌名称]（一家[行业]公司）的[主题]。 [抽象——程式化/高度抽象]表示，简化为基本的几何形式。在[构造——圆形/网格/黄金比例]框架上构建。 [线条质量] 边缘经过[填充样式] 处理。白色背景上的单色[颜色]。该符号所暗示的[视觉隐喻]超出了其字面形式。足够干净，可以在 16 像素图标大小下工作。没有文字，纯粹的符号。Vector quality, professional logo presentation, centered composition, generous whitespace. Flat design, no gradients, no 3D effects, no shadows.
````

### 3.4 抽象标记

**它传达的信息：** 独特性和可拥有的视觉领域。与参考真实物体的图形标记不同，抽象标记创造了全新的形式。它们通过形状心理学进行交流——角=动态，圆形=统一，有机=人性化。

**设计规则：**
- 形状必须真正独特——而不是现有品牌标志的衍生品
- 形状心理学驱动意义：圆形（团结、社区）、三角形（方向、野心）、流动形式（灵活性、创造力）
- 必须使用单色
- 对称创造稳定性；不对称创造能量
- 形式应该让人感觉是不可避免的——就好像它不可能是任何其他方式一样

**标志规范框架：**
````
标志类型：抽象标志
品牌名称：[品牌名称]
行业：[行业]
形状语言：[角度/圆形/有机/混合]
心理信息：[形状传达的信息——统一/方向/成长/速度/稳定]
对称性：[对称/不对称/旋转]
施工方法：【几何重叠/负空间/连续线/碎片】
动态质量：[静态/建议运动/变形]
颜色: [原色或多色]
````

**AI图像提示--抽象标记标志概念：**
````
[品牌名称]（[行业] 公司）的专业抽象徽标。使用[形状语言]形状的独特几何抽象形式。该形式通过纯粹的形状心理学来传达[心理信息]。 [对称]与[施工方法]组成。形状暗示着[动态品质]。 [颜色处理——单色/渐变/多色]。比例中可见清晰的数学结构。该标志给人一种拥有感和独特感——与任何现有的品牌符号不同。矢量质量，白色背景上的专业徽标呈现，居中，慷慨的空白。干净的平面设计。
````

### 3.5 吉祥物标志

**它传达的信息：** 平易近人、个性、友善。吉祥物使品牌人性化并建立情感联系。最适合面向家庭、娱乐、餐饮服务和社区的品牌。

**设计规则：**
- 必须从姿势和表情中立即看出性格
- 简化可扩展性——吉祥物必须在小尺寸下工作
- 定义角色表：正面、侧面、表情、姿势
- 吉祥物应体现品牌个性，而不仅仅是装饰
- 避免阻碍跨媒体复制的复杂性

**标志规范框架：**
````
标志类型：吉祥物
角色：[吉祥物是什么——动物/人/物体/生物]
品牌名称：[品牌名称]
行业：[行业]
性格：[友善/精力充沛/聪明/顽皮/英雄]
艺术风格：[平面矢量/插图/卡通/简约/现实]
表情：[默认表情——微笑/坚定/好奇/俏皮]
调色板：[角色的主要颜色]
姿势：[默认姿势——站立/挥手/动作/肖像]
详细程度：[最小/中等/详细]
````

**AI图像提示--吉祥物标志概念：**
````
专业吉祥物标志设计，以[品牌]（一家[行业]公司）的[角色]为特色。 【艺术风格】插画风格。角色具有[个性]个性，以[姿势]姿势和[表情]表情表现出来。 [COLORS] 的调色板。 [细节级别] 细节级别，旨在从广告牌到名片。人物设计轮廓清晰。富有表现力的眼睛和肢体语言传达[个性]。干净的背景，专业的标志呈现质量。吉祥物感觉像是一个受人喜爱的品牌角色，而不是一个普通的卡通人物。矢量插图质量、简洁的线条、一致的笔划粗细。
````

### 3.6 徽章/徽章

**它传达的信息：** 传统、权威、归属感、制度自豪感。标志给人一种正式和确定的感觉。封闭的形式创造了一种“会员身份”的感觉——你要么在徽章之内，要么在徽章之外。

**设计规则：**
- 文字和符号是不可分割的——它们形成一个整体
- 最常见的是圆形、盾形或横幅形容器
- 细节水平必须平衡传统感和可扩展性
- 内饰应具有清晰的视觉层次：主要符号、品牌名称、次要文字
- 非常适合邮票、补丁、徽章和印章

**标志规范框架：**
````
标志类型： 徽章/徽章
品牌名称：[品牌名称]
行业：[行业]
容器形状：[CIRCLE / SHIELD / BADGE / BANNER / CREST / HEXAGON]
内部符号：[中心图标或插图]
文本位置：[周围/下面的横幅/集成]
传承元素：[星星/桂冠/卷轴/年份/座右铭]
复杂程度：[简约-现代/中等/详细-传统]
颜色：[原色]
````

**AI图像提示--会徽标志概念：**
````
[品牌名称]（一家[行业]公司）的专业徽章徽标。 [容器形状] 以[内部符号]为中心元素的容器。品牌名称 [文本位置] 采用 [印刷风格 -- 衬线/无衬线/哥特式] 字体。 [遗产元素] 添加 [复杂程度] 级别的传统细节。 [COLORS] 的调色板。该标志感觉就像是品质和传统的官方印章。内部元素排列清晰，视觉层次分明。可用作徽章、印章或补丁。白色背景上的专业徽标演示，居中。干净的矢量质量，精确的线条工作和一致的笔划粗细。
````

### 3.7 组合标记

**它传达的信息：** 多功能性和认知度建设。组合标记将符号与文字标记配对，为品牌提供了两条识别路径。我们的目标是最终分离——有一天，符号将独自承载品牌。

**设计规则：**
- 符号和文字标记必须设计为一个系统，而不是螺栓连接在一起
- 定义空间关系：符号左、上、右或集成
- 两个元素必须独立工作（长期测试）
- 符号和文本之间的对齐和间距至关重要
- 创建锁定变体：水平、堆叠、仅符号、仅文字标记

**标志规范框架：**
````
标志类型：组合标志
品牌名称：[品牌名称]
行业：[行业]
符号：[图标/符号的描述]
文字标记样式：[排版样式]
空间关系：[符号左/符号上/符号右/集成]
所需的锁定变化：[水平/堆叠/仅符号/仅文字标记]
视觉权重平衡：[符号主导/文本主导/平等]
颜色：[原色]
````

**AI图像提示--组合标志标志概念：**
````
[品牌名称]（[行业] 公司）的专业组合标志。干净的[符号描述]符号与自定义的[文字标记样式]排版配对。 [空间关系] 具有精确对齐和间距的排列。符号和文字标记具有相同的视觉DNA——一致的线宽、比例和谐、统一的设计语言。图标和文本之间的[视觉重量平衡]。白色背景上的单色[颜色]。该符号足够独特，可以单独使用，文字商标足够精致，可以独立存在。专业的标志展示，居中的构图，慷慨的留白。矢量品质，平面简洁的设计。
````

### 3.8 动态/响应式标志

**它传达的信息：** 适应性、现代性、生动的品牌能量。动态徽标根据上下文改变形式、颜色或细节，同时保持核心识别度。它们表明品牌是有活力的，而不是静止的。

**设计规则：**
- 定义不变的核心：永远不会改变的东西（通常是基本形状或结构）
- 定义变量层：可以改变什么（颜色、图案、细节、图像）
- 创建一个变化系统，而不是随机变化
- 每个变体必须能够立即被识别为同一品牌
- 响应式缩放：全标记 -> 简化标记 -> 图标 -> favicon，每一个都经过精心设计

**标志规范框架：**
````
标志类型：动态/响应式
品牌名称：[品牌名称]
行业：[行业]
不变的核心：[保持不变的——形状/结构/比例]
可变层：[发生了什么变化——颜色/图案/填充/图像/细节]
变化系统：[规则变化——季节性/情境/随机/数据驱动]
变化数量：[有多少个��义的状态]
响应级别：[完整/简化/图标/FAVICON]
识别锚：[是什么使它始终可识别]
````

**AI图像提示--动态标识系统：**
````
为[行业]公司[品牌]设计的专业动态标志系统。显示排列在 2x2 网格中的同一徽标的 4 个变体。所有变体都具有相同的[不变核心——基本形状/结构]，但每个变体都有不同的[可变层——调色板/内部图案/填充图像/纹理处理]。变化 1：[主题 A]，变化 2：[主题 B]，变化 3：[主题 C]，变化 4：[主题 D]。尽管存在差异，但���四个产品都可以立即被识别为同一品牌。干净的矢量质量，每个变化都在其自己的框架中，并且大小一致。白色背景上的专业徽标系统演示。平面简洁的设计，所有变体的结构一致。
````

### 3.9 徽标净空间和尺寸规则

**它传达的信息：** 专业纪律。清晰的空间规则确保标志始终会呼吸，并且不会感到局促、拥挤或被周围元素削弱。

**设计规则：**
- 最小净空间：通常是所有侧面的关键字母（通常是字标中的“x”）的高度
- 没有任何东西进入清晰的空间——没有文本、没有图像、没有边框、没有图案
- 最小复制尺寸：分别定义印刷（毫米）和数字（像素）
- 背景规则：定义批准的背景颜色和图像处理
- 联合品牌规则：徽标如何与合作伙伴徽标一起出现

**规范框架：**
````
徽标空白规则：
测量单位：[关键字母或具体测量]
最小净空间：所有四个边上的 [X] 个单位
最小打印尺寸：[WIDTH in mm] 宽
最小数字尺寸：[WIDTH in px] 宽
批准的背景：[列表 - 白色、黑色、品牌主色、叠加摄影]
摄影放置：[规则——最小对比度、位置偏好]
联合品牌间距：[与合作伙伴徽标的最小距离]
````

**AI图像提示--清晰空间图：**
````
[品牌] 的专业徽标清晰空间和最小尺寸规格图。简洁的技术插图显示徽标以虚线边界为中心，指示最小净空间区域，使用 [测量单位] 进行测量。显示精确间距要求的箭头和尺寸标签。下图：最小尺寸示例，显示徽标的尺寸逐渐变小，并明确标记了可接受的最小尺寸。右侧：经批准的背景示例 - 白色徽���、黑色徽标、品牌颜色徽标、带有叠加层的照片。底部：不正确的放置示例用红色 X 标记划掉。干净的技术图表风格、精确的测量、专业的品牌指南页面布局。白色背景，干净的无衬线注释文本。
````

### 3.10 徽标滥用示例

**它传达的信息：** 保护品牌完整性。滥用示例准确地展示了不该做的事情，防止合作伙伴、供应商和内部团队进行善意但具有破坏性的修改。

**常见误用类别：**
- 请勿拉伸、倾斜或扭曲比例
- 请勿旋转徽标
- 请勿更改认可调色板之外的徽标颜色
- 不要添加阴影、轮廓或效果
- 未经批准的处理，请勿放置在繁忙的背景上
- 不要重新排列徽标元素（相对于文字标记移动符号）
- 不要使用过时的版本
- 请勿重新创建或近似徽标 - 始终使用官方文件
- 请勿裁剪徽标或侵犯空白空间
- 不要在徽标锁定中添加额外的文本或标语

**规范框架：**
````
徽标滥用预防指南：

切勿执行以下操作：
1. 拉伸或压缩：始终保持精确的比例
2. 旋转：Logo必须保持0度旋转
3. 重新着色：仅使用认可的颜色版本
4. 添加效果：无阴影、发光、轮廓、斜角或纹理
5. 低对比度：切勿放置在降低易读性的背景上
6. 重新排列：符号和字标位置固定
7. 重新创建：始终使用官方徽标文件，切勿重新输入或重新绘制
8. 裁剪：完整的徽标必须始终可见
9.未经批准就制作动画：动画版本需要品牌团队签字10. 合并：不要与其他标志或图标合并成一个复合标志
````

**AI图像提示--Logo误用指南：**
````
[BRAND NAME] 品牌指南的专业徽标滥用示例页面。干净的网格布局显示 8-10 个不正确徽标使用的示例，每个示例都带有红色 X 或禁止符号。示例包括：拉伸徽标、旋转徽标、错误颜色、添加阴影、无对比地放置在繁忙的照片上、重新排列元素、裁剪徽标、轮廓版本、低分辨率像素化版本、添加未经授权的标语的徽标。每个滥用示例都清楚地标有简短的禁止声明。干净的技术图表风格，白色背景，有组织的网格布局。正确的徽标显示在顶部一次以供参考。专业品牌指南页面质量。
````

---

## 模块 4：色彩系统——情感和功能架构

颜色是品牌系统中最快的沟通者。在读到一个词之前，颜色就已经表达了自己的观点：值得信赖还是有趣、优质还是平易近人、传统还是创新。该模块构建了从心理学到实施的完整色彩系统。

### 4.1 单色系统

**它传达的信息：** 成熟、专注、视觉平静。单色系统在各种色调、色调和色调下使用一种色调。上面写着：“我们对自己的身份非常有信心，一种颜色就足够了。”

**设计规则：**
- 从一种强烈的基色开始
- 从近白色调到近黑色调建立 5-7 个步骤
- 使用亮度变化来表达层次结构（较亮=次要，较暗=强调）
- 为文本和 UI 元素添加单一中性色（暖灰色或冷灰色）
- 系统从克制中获得力量——抵制添加第二种色调

**颜色规范框架：**
````
颜色系统：单色
基本色调：[颜色名称] -- [十六进制值]
色调 1（最浅）：[HEX] -- 背景，微妙的填充
色调 2：[HEX] -- 辅助背景、悬停状态
色调 3：[HEX] -- 边框、分隔线
基础（中）：[HEX] -- 主要品牌应用
阴影 1：[HEX] -- 标题、强调
阴影 2（最暗）：[HEX] -- 文本、高对比度元素
中性：[WARM GREY 或 COOL GREY HEX] -- 正文、次要内容
白色：#FFFFFF——主要背景
比例：60% 最浅色调/30% 中暗/10% 最暗色调
````

**AI图像提示--单色品牌视觉：**
````
精致的单色品牌视觉仅使用各种色调和色调的[基础颜色]。优雅的分层构图，具有重叠的几何形状，每种形状都有不同的[颜色]值——从近乎白色的耳语到深沉的深色。值之间的平滑渐变创建深度和维度。最深色的干净无衬线字体。大面积的最浅色调作为呼吸空间。该构图表明，巧妙使用单一颜色可以产生比彩虹更大的影响。最小布局和精确间距。4K、优质图形设计品质、瑞士精准设计。
````

### 4.2 类比系统

**它传达的信息：** 和谐、自然之美、凝聚力。类似的颜色在色轮上彼此相邻，创造出一种感觉有机、统一和舒适的调色板。

**设计规则：**
- 在色轮上选择2-4个相邻的色调（跨度不超过90度）
- 一种色调占主导地位，其他色调支持——避免平均分配
- 温度保持一致（全部温暖或全部凉爽）
- 最适合想要感觉自然、有机或和谐的品牌
- 添加中性物质（奶油、木炭）用于接地

**颜色规范框架：**
````
颜色系统：类似色
主要色调：[COLOR A] -- [HEX] -- 占主导地位，使用率 60%
次要色调：[COLOR B] -- [HEX] -- 支持，25% 使用率
第三色调：[COLOR C] -- [HEX] -- 重音，10% 使用率
中性：[暖/冷中性] -- [十六进制] -- 文本和结构，5%
温度：[暖/冷]
心情：[自然/宁静/活力/朴实]
````

**AI图像提示--类比色品牌视觉：**
````
使用[颜色A]、[颜色B]和[颜色C]的类似调色板实现和谐的品牌视觉效果。流动的有机构图，色彩自然地融合在一起，就像日落或风景一样。 [颜色 A] 在构图中占主导地位，占 60%，[颜色 B] 作为支撑元素，[颜色 C] 作为微妙的强调元素。色调之间平滑、自然的过渡。有机的弯曲形状暗示着自然形态——树叶、波浪、地形。整个温度温暖[或凉爽]。调色板感觉统一且轻松，就像在大自然中发现的颜色一样。深色中性的干净排版。 4K、编辑设计品质、自然和谐美感。
````

### 4.3 补充系统

**它传达的信息：** 能量、对比度、视觉冲击力。互补色在色轮上彼此相对，产生最大的对比度和充满活力的张力。象征着大胆、自信和引人注目的品牌。

**设计规则：**
- 使用一种颜色作为主色（70-80%），使用补色作为强调色（20-30%）
- 切勿以等比例使用 - 会产生视觉振动和不适
- 使一种或两种颜色静音，以适应复杂的应用
- 补语是你的“强力口音”——用它来表达号召性用语、亮点、关键元素
- 中立者是两个对立力量之间的重要桥梁

**颜色规范框架：**
````
颜色系统： 互补色
原色：[COLOR A] -- [HEX] -- 占主导地位，使用率 70%
补色：[COLOR B] -- [HEX] -- 重音，20% 使用率
中性桥：[灰色/奶油色/木炭] -- [十六进制] -- 10%
静音主要：[去饱和版本]--[十六进制]--适用于大面积
静音补码：[去饱和版本] -- [十六进制] -- 用于背景
使用规则：切勿以相等面积比使用主补色
````

**AI图像提示——互补色品牌视觉：**
````
使用 [COLOR A] 和 [COLOR B] 互补调色板呈现大胆的高对比度品牌视觉效果。 [颜色 A] 作为主要品牌颜色占成分的 70%。 [颜色 B] 在 20% 的区域中呈现出强烈的强调效果——大胆的条纹、关键元素、焦点。这种对比产生了强烈的视觉能量和即时的注意力。具有锐利干净边缘的几何形状。深色中性[灰色/炭]用于文本和结构。构图展现出受控的张力——大胆但不混乱。干净的现代布局与不对称的平衡。 4K、海报设计品质，视觉冲击力强。
````

### 4.4 分裂互补系统

**它传达的信息：** 复杂的对比，但没有纯粹互补的攻击性。使用一种基色加上与其补色相邻的两种颜色，创造出一个充满张力与和谐的平衡三角形。

**设计规则：**
- 一种主色，两种强调色位于其补充色两侧
- 比纯粹的互补更加细致和灵活
- 两种强调色共享温暖/凉爽，创造自然的搭配
- 非常适合希望充满活力且平易近人的品牌
- 适用于数据可视化和复杂布局

**颜色规范框架：**
````
颜色系统：分色互补
基色：[COLOR A] -- [HEX] -- 占主导地位，60%
分割重音 1：[COLOR B] -- [HEX] -- 重音，20%
分割重音 2：[COLOR C] -- [HEX] -- 重音，15%
中性：[十六进制] -- 5%
关系：[颜色 B] 和 [颜色 C] 位于 [颜色 A] 的补色两侧
````

**AI形象提示——分裂互补的品牌视觉：**
````
使用分裂互补调色板的复杂品牌视觉效果。 [颜色 A] 作为主色，占构图的 60%。 [颜色 B] 和 [颜色 C] 作为平衡的强调色，提供对比而不具有攻击性。具有重叠半透明形状的几何构图，在元素相交处创建新的颜色交互。调色板给人一种充满活力但又控制欲强、充满活力但又和谐的感觉。现代不对称布局，具有由颜色权重驱动的清晰视觉层次。中性暗色调的干净排版。4K、当代图形设计品质、平衡的视觉能量。
````

### 4.5 三元系统

**它传达的信息：** 多样性、活力、有趣的能量。色轮上均匀分布的三种颜色创造出丰富、平衡和动态的调色板。最适合想要充满活力、多元化和活力的品牌。

**设计规则：**
- 色轮上间隔 120 度的三种颜色
- 一主宰，二支持——从来不相等
- 高饱和度创造俏皮能量；柔和的饱和度营造出精致感
- 非常适合针对年轻受众、创意产业或多元化社区的品牌
- 需要小心平衡——没有约束容易变得混乱

**颜色规范框架：**
````
颜色系统：三元色
颜色 A：[COLOR] -- [HEX] -- 占主导地位，50%
颜色 B：[颜色] -- [十六进制] -- 次要，30%
颜色 C：[COLOR] -- [HEX] -- 重音，15%
中性：[十六进制] -- 5%
饱和度级别：[全/静音/混合]
能量水平：[有趣/平衡/成熟]
````

**AI图像提示——三色品牌视觉：**
````
使用[颜色A]、[颜色B]和[颜色C]的充满活力的三色品牌视觉。 [颜色 A] 占主导地位 50%、[颜色 B] 占 30%、[颜色 C] 占 15% 的动态构图。大胆的几何形状——圆形、三角形和矩形——排列成充满活力的不对称构图。颜色在交叉点相互作用，产生二次混合。调色板给人一种充满活力、多样化和庆祝的感觉。 [饱和度——完全饱和表示俏皮/静音表示精致]。干净的现代无衬线字体。白色或浅色中性背景让色彩可以歌唱。 4K、充满活力的海报设计品质，包豪斯遇上当代能量。
````

### 4.6 深色模式色彩系统

**它传达的信息：** 现代性、复杂性、以用户为中心的思维。深色模式不仅仅是“反转颜色”——它需要一个完全重新思考的颜色系统，以保持品牌形象，同时减少眼睛疲劳。

**设计规则：**
- 背景不是纯黑色 (#000000) - 使用提升的深灰色 (#121212 到 #1E1E1E)
- 对于深色背景，品牌颜色必须去饱和并变亮（增加 HSL 中的 L 值）
- 文本不是纯白色 (#FFFFFF) - 使用稍暖的灰白色（#E0E0E0 到 #F5F5F5）
- 仰角 = 较亮的表面，而不是阴影（与光照模式相反）
- 强调色需要更高的亮度来维持对比度
- 测试所有颜色组合是否符合 WCAG AA 最小值（���本为 4.5:1）

**颜色规范框架：**
````
深色模式颜色系统：
Background Level 0: [HEX] -- #121212 to #1A1A1A (deepest surface)
Background Level 1: [HEX] -- +5% white overlay (cards, containers)
Background Level 2: [HEX] -- +8% white overlay (elevated elements)
Background Level 3: [HEX] -- +11% white overlay (top-level surfaces)
Primary Brand (adjusted): [HEX] -- lightened, desaturated from light-mode primary
Secondary Brand (adjusted): [HEX] -- lightened for dark background legibility
Text Primary: [HEX] -- 87% opacity white (#E0E0E0)
Text Secondary: [HEX] -- 60% opacity white (#9E9E9E)禁用文本：[HEX] -- 38% 不透明度白色 (#636363)
错误：[HEX] -- 深色背景变亮红色
成功：[HEX] -- 深色背景变浅绿色
````

**AI图像提示--深色模式品牌视觉：**
````
[BRAND NAME] 的复杂深色模式品牌界面设计。深木炭背景（#1A1A1A，不是纯黑色），升高的卡片表面呈逐渐变浅的灰色。品牌颜色 [COLOR A] 和 [COLOR B] 针对深色背景进行了调整 - 稍微降低饱和度并提高亮度。文本采用暖灰白色 (#E8E8E8)，辅助文本采用柔和的灰色。微妙的高程阴影使用较暗的值，而不是浅色阴影。具有圆角和精确间距的 UI 元素。深色主题给人一种高级且舒服的感觉，而不是阴暗的。强调色在深色表面上发出柔和的光芒。 4K、现代 UI 设计品质、Apple/Figma 深色模式美学。
````

### 4.7 无障碍颜色系统（WCAG 合规性）

**它传达的信息：** 包容性、责任感、专业成熟度。易于使用的色彩系统可确保每个人（包括 3 亿有色觉缺陷的人）都能感知和使用该品牌的视觉传达信息。

**设计规则：**
- 普通文本：与背景的对比度至少为 4.5:1 (WCAG AA)
- 大文本（18px+ 或 14px+ 粗体）：最小对比度 3:1 (WCAG AA)
- 增强：7:1 符合 AAA 合规性
- 切勿仅通过颜色传达含义 - 始终与文本、图标或图案配对
- 使用色盲模拟器进行测试（红色盲、绿色盲、蓝色盲）
- 为交互状态（悬停、聚焦、活动）提供足够的对比度

**颜色规范框架：**
````
无障碍色彩系统：
主色为白色：[HEX] -- 对比度 [X:1] -- [PASS/FAIL AA] [PASS/FAIL AAA]
深色主色：[HEX] -- 对比度 [X:1] -- [PASS/FAIL AA] [PASS/FAIL AAA]
白色次要：[HEX] -- 对比度 [X:1]
主要文本：[HEX] -- 对比度 [X:1]
链接颜色：[HEX]——必须与正文区分开来并满足对比
错误红色：[HEX] -- 与 [ICON/PATTERN] 配对，适合色盲用户
成功绿色：[HEX] -- 与 [ICON/PATTERN] 配对，适合色盲用户
警告：[HEX] -- 与 [ICON/PATTERN] 配对色盲安全调色板：在红色盲、绿色盲、蓝色盲下可区分所有关键颜色
````

**AI图像提示--可访问的颜色演示：**
````
[品牌] 的专业易用色彩系统演示。干净的网格布局显示颜色样本及其十六进制值和 WCAG 对比度。每种颜色都与白色、黑色和品牌背景搭配，并带有通过/失败指示器。侧面板显示了在三种色盲（红色盲、绿色盲、蓝色盲）下模拟的相同界面。正确使用的示例：带有红色和警告图标的错误状态，用颜色和下划线区分的链接。干净的数据可视化风格布局，信息丰富且精确。 4K、品牌指南页面质量、可访问性文档美观。
````

### 4.8 色彩心理学快速参考

将颜色映射到心理关联、文化背景和品牌原型的快速参考指南。不是绝对的规则——由文化背景和组合效应塑造的指导方针。

**色彩-情感-产业地图：**
````
色彩心理学快速参考

红色：能量、激情、紧迫感、危险、食欲
  行业：食品、娱乐、体育、应急、零售
  品牌：可口可乐、Netflix、YouTube、Target、CNN
  注意：可以在金融环境中发出危险/债务信号

橙色：热情、创造力、温暖、负担能力、冒险精神
  行业：科技、食品、娱乐、青年品牌
  品牌：亚马逊、芬达、Nickelodeon、Soundcloud、Etsy
  注意：很少被解读为优质或奢华

黄色：乐观、幸福、温暖、谨慎、智慧
  行业：食品、能源、儿童、交通
  品牌：麦当劳、宜家、Snapchat、国家地理、DHL
  注意：白色对比度低——可访问性挑战

绿色：自然、健康、成长、财富、可持续性、平静
  行业：健康、金融、有机、环境、农业
  品牌：星巴克、Spotify、全食超市、约翰迪尔、BP
  注意：在健康/生态中过度使用——更难区分

蓝色：信任、稳定、专业、冷静、技术
  行业：金融、科技、医疗保健、企业、社交媒体
  品牌：Facebook、IBM、三星、PayPal、LinkedIn、福特
  注意：在企业中过度使用——可能会感觉很普通，没有区别

紫色：奢华、创造力、智慧、灵性、神秘
  行业：美容、奢侈品、教育、精神、创意
  品牌：吉百利、Twitch、FedEx Accent、Hallmark、雅虎
  注意：如果太明亮会显得幼稚，如果过度使用会显得自命不凡

粉色：俏皮、浪漫、同情、青春、女性气质
  行业：美容、时尚、美食、约会、儿童
  品牌：T-Mobile、Barbie、Lyft、Cosmopolitan、维多利亚的秘密
  注意：文化中的性别关联差异很大

黑色：奢华、力量、精致、优雅、权威
  行业：时尚、奢侈品、汽车、科技、媒体
  品牌：香奈儿、耐克、苹果、普拉达、优步
  注意：过度使用会产生沉重感——与空白保持平衡

白色：纯洁、简约、干净、现代、空间
  行业：医疗保健、科技、婚礼、简约品牌
  品牌：苹果（使用）、特斯拉、无印良品、The White Company
  注意：如果没有温暖的元素，纯白色会让人感觉无菌

金奖：优质、成就、传统、成功、温暖
  行业：奢侈品、金融、奖项、烈酒、珠宝
  品牌：劳力士、范思哲、酩悦、瑞士莲
  注意：金属复制需要特殊的印刷工艺
````

### 4.9 行业颜色约定

了解您的行业期望什么颜色 - 这样您就可以遵守或故意打破这些惯例。

**行业色彩图：**
````
行业颜色惯例

金融与银行：海军蓝、深绿、金色、木炭色
  大会理由：信任、稳定、财富关联
  颠覆机会：使用珊瑚色、紫色、亮绿色的金融科技品牌（Monzo、Nubank、Robinhood）

医疗保健和制药：蓝色、绿色、白色、浅青色
  大会理由：清洁、平静、信任、科学
  颠覆机会：使用暖土色调、黄色的心理健康品牌（Headspace、Calm）

科技：蓝色、紫色、渐变、黑白
  大会理由：创新、信任、数字原生感觉
  颠覆机会：使用暖色、俏皮调色板的消费者技术（Slack、Notion）

食品和饮料：红、黄、橙、绿（有机）
  约定理由：刺激食欲、能量、新鲜
  颠覆机会：使用黑色、海军蓝、金色的优质食品（Nespresso、Blue Bottle）

时尚与奢华：黑色、白色、金色、深宝石色调
  大会理由：精致、永恒、优质信号
  颠覆机会：使用霓虹灯、涂鸦颜色的街头服饰（Supreme、Off-White）

教育色：蓝色、栗色、绿色、金色
  大会理由：知识、传统、成长、成就
  颠覆机会：使用明亮、有趣的调色板的教育科技（Duolingo、可汗学院）

房地产：蓝色、绿色、金色、酒红色
  大会理由：信任、成长、价值、传承
  颠覆机会：使用珊瑚、现代中性元素的 PropTech（Zillow、Compass）

可持续发展与生态：绿色、大地色、海蓝色
  大会理由：自然、环境、有机
  颠覆机会：气候技术使用意想不到的大胆颜色来表示紧迫性
````

### 4.10 色彩比例规则 -- 60/30/10 原则

确保任何调色板在应用中发挥作用的基本比例系统。如果没有比例规则，即使是最好的颜色也会造成视觉混乱。

**设计规则：**
- 60% 主导：主要品牌颜色或中性色——设定整体情绪
- 30% 次要：支持主导并与主导形成对比——创造视觉兴趣
- 10% 口音：引人注目——CTA、亮点、特殊时刻
- 此比例适用于各种比例：整页、单个部分、单个组件
- 强调色是你最强大的工具——精确地使用它

**色彩比例规格：**
````
色彩比例系统（60/30/10）：

60% -- 主导：[颜色/十六进制]
  用于：主要背景、大表面、整体页面颜色
  这会设定室温——这是人们吸收的第一种颜色

30% -- 次要：[颜色/十六进制]
  用于：导航、侧边栏、卡片、辅助表面、支持内容区域
  这创造了与主流的对比和视觉节奏

10% -- 重音：[颜色/十六进制]
  用于：号召性用语按钮、链接、图标、通知徽章、关键亮点
  这是眼睛首先看到的地方——用它来引导注意力到最重要的事情上

高级变化：
- 60/30/10，中性为主：60% 白色 + 30% 品牌主色 + 10% 口音
- 60/30/10，品牌占主导地位：60% 品牌主要 + 30% 中性 + 10% 补充
- 70/25/5 奢华：更加克制，口音变得稀有而珍贵
- 50/30/15/5 适用于复杂的 UI：具有主要、次要、第三、重音的四色系统

申请规则：
根据这个比例检查每个布局。如果您无法确定哪种颜色具有哪种作用，则调色板不起作用。
````

**AI图像提示--色彩比例演示：**
````
[BRAND NAME] 品牌指南的专业色彩比例演示。干净的布局显示了应用于示例网页设计的 60/30/10 规则。主色 [60% 颜色] 覆盖主要背景区域。辅助颜色 [30% 颜色] 出现在导航、侧边栏和卡片元素中。强调色 [10% 颜色] 仅突出显示 CTA 按钮、关键图标和一个通知徽章。��面标注了百分比标签和色样。下图：三个变体，显示具有不同 60/30/10 分布的相同布局。干净、精确、信息丰富的图表风格。 4K，品牌指南文档质量。
````

