## 模块 5：版式系统——言语个性视觉化

版式是您品牌的声音。你选择的字体在人们读到一个单词之前就已经告诉了他们你是谁。该模块涵盖了每个主要类型分类、配对策略和层次系统。

### 5.1 几何无衬线字体

**它传达的信息：** 现代、精确、几何完美。由圆形、正方形和三角形组成。这些字母给人的感觉是经过精心设计的，而不是绘制出来的。信号：技术、创新、清洁效率。

**代表性字体：** Futura、Montserrat、Poppins、Circular、Avenir、Gotham、Century Gothic

**设计规则：**
- 完美的圆构成 O、C、G 的基础——创造数学和谐
- 整个笔划宽度均匀（单线性或近单线性）
- 最适合标题和品牌标志；较长的正文会让人感到寒冷
- 与人文主义衬线完美搭配，形成温暖对比
- 严格跟踪标题，稍微开放跟踪正文

**排版规范：**
````
类型分类：几何无衬线字体
主要字体：[字体名称]
使用的粗细：[浅色/常规/中度/粗体/黑色]
标题处理：[WEIGHT]、[SIZE]px/pt、跟踪[VALUE]、[CASE -- 大写/标题/小写]
正文处理：[WEIGHT]、[SIZE]px/pt、行高 [VALUE]、跟踪 [VALUE]
品牌个性匹配：现代、精确、科技前沿、简洁、数学
避免：长篇阅读、温暖/个人品牌、传统行业
配对：[互补字体——通常是人文主义衬线或文本优化的无衬线]
````

**人工智能图像提示-几何无版式视觉：**
````
版式样本展示采用几何无衬线字体[字体名称]为[品牌名称]。 [重量] 粗细的大标题显示完美的几何字母形式 - 请注意圆形 O、三角形 A，数学上精确的比例。以大写和小写形式大规模显示完整字母表。下面：一段展示可读性的正文。颜色：标题为 [品牌颜色]，正文为深炭色，背景为干净的白色。字母形状的几何精度营造出一种工程美感。网格线微妙可见，显示了数学结构。 4K、排版样本品质、字体铸造呈现美感。
````

### 5.2 怪诞/新怪诞

**它传达的信息：**中立、普遍性、专业信心。这些是“隐形”字体——它们传达内容而不引起人们的注意。信号：企业可靠性、廉洁专业精神、普遍可及性。

**代表性字体：** Helvetica、Arial、Inter、Aktiv Grotesk、Neue Haas Grotesk、Univers、Suisse Int''l

**设计规则：**
- 笔划宽度略有不同（不像几何那样完全单线性）
- 中性特征——不将个性强加于内容
- 跨尺寸和环境的多功能性
- 永远不会失败但很少令人兴奋的“安全”选择
- 差异化来自于粗细、间距和使用规则，而不是字母形式

**排版规范：**
````
类型分类：怪诞/新怪诞无衬线
主要字体：[字体名称]
使用的粗细：[常规/中号/半粗体/粗体]
标题处理：[WEIGHT]、[SIZE]、跟踪[VALUE]、[CASE]
主体处理：[重量]、[尺寸]、行高[1.5-1.6]、跟踪[0到+10]
品牌个性匹配：中立、专业、可靠、通用、企业
避免用于：需要强烈视觉个性或通过类型进行差异化的品牌
搭配：[用于编辑对比的衬线或用于标题个性的显示字体]
````

**AI图像提示——新怪诞的排版视觉效果：**
````
干净的专业版式样本，具有新怪诞字体 [字体名称] 的 [品牌名称]。标题采用 [WEIGHT] 粗细，展示了字体中性、自信的特征。完整的字母显示显示了微妙的笔画变化和精致的字母比例，使其与几何无衬线字体区别开来。正文段落表现出出色的可读性和中性语气。排版本身并不引起人们的注意——它让内容说话。颜色：[品牌颜色]标题，近黑色主体，白色背景。最小布局，完美对齐和间距。 4K，专业型标本品质，国际风格审美。
````

### 5.3 人文主义无衬线字体

**它传达的信息：** 现代形式中的温暖、平易近人、人性化。基于有机笔画调制的手写比例。信号：友好的技术、医疗保健、教育、想要现代但温暖的品牌。

**代表性字体：** Gill Sans、Frutiger、Open Sans、Lato、Source Sans Pro、Myriad Pro、Calibri

**设计规则：**
- 笔画宽度略有变化，模仿笔压力
- 开放式光圈（c、e、a 等字母中的开口）提高了可读性
- 比怪诞更温暖，比几何更少个性
- 非常适合正文——最具可读性的无衬线字体类别
- 与平板衬线或显示字体完美搭配

**排版规范：**
````
类型分类： 人文主义无衬线字体
主要字体：[字体名称]
使用的粗细：[LIGHT / REGULAR / SEMIBOLD / BOLD]
标题处理：[重量]、[尺寸]、跟踪[值]
主体处理：[重量]、[尺寸]、线高[1.5-1.7]
品牌个性匹配：热情、友善、平易近人、人性化、值得信赖
最适合：医疗保健、教育、政府、社区品牌、长篇内容
配对：[GEOMETRIC SANS 用于对比或 TRANSITIONAL SERIF 用于经典配对]
````

**AI 图像提示 -- Humanist Sans Typography 视觉效果：**
````
温馨平易近人的版式样本，采用人文主义无衬线字体 [字体名称] 代表 [品牌名称]。标题以 [WEIGHT] 字重显示有机的、手工影响的比例 - 请注意书法笔画变化和开放字母孔径。全字母显示强调设计的温暖性和可读性。正文段落展示了舒适的扩展阅读体验。排版感觉既现代又人性化——就像一位知��渊博的朋友清晰地说话一样。颜色：【暖色品牌色】标题，暖色深灰色主体，柔和的灰白色背景。宽大的边距和行高。 4K，类型标本品质，温馨专业美感。
````

### 5.4 过渡衬线

**它传达的信息：** 权威、可信度、编辑质量。旧式衬线与现代衬线之间的桥梁——精致但不极端。信号：新闻业、出版业、法律、金融、知名机构。

**代表性字体：** Times New Roman、Baskerville、Georgia、Charter、Libre Baskerville、Noto Serif

**设计规则：**
- 粗细笔画之间的适度对比
- 带逐渐过渡的括号衬线
- 垂直应力轴（直立、正式姿势）
- 正文大小具有出色的可读性
- 立即传达情报和编辑可信度

**排版规范：**
````
类型分类: 过渡衬线
主要字体：[字体名称]
使用的粗细：[常规/斜体/半粗体/粗体]
标题处理：[重量]、[尺寸]、跟踪[值]
主体处理：[重量]、[尺寸]、线高[1.6-1.8]
品牌个性匹配：权威、编辑、可信、制度、智能
最适合：出版、媒体、法律、��融、教育、编辑品牌
搭配：[GROTESQUE SANS 体现现代对比，HUMANIST SANS 体现温暖]
````

**AI图像提示--过渡衬线字体视觉效果：**
````
权威的编辑版式样本，采用[品牌名称]的过渡衬线字体[字体名称]。 [重量] 粗细的大标题展示了精致的笔画对比度和优雅的括号衬线。显示带有斜体变体的完整字母表，显示经典比例。正文段落展示了字体卓越的可读性和编辑权威。排版感觉就像一份受人尊敬的报纸或期刊的头版。颜色：深木炭色或海军蓝，用于温暖象牙色背景上的文本。经典比例，宽裕边缘。 4K、社论出版品质、纽约时报审美。
````

### 5.5 现代/Didone 衬线体

**它传达的信息：** 高级时尚、极致优雅、戏剧性的精致。粗细笔画之间的最大对比度，带有细线衬线。信号：奢华、时尚、美容、艺术、高端社论。

**代表性字体：** Bodoni、Didot、Playfair Display、Italiana、Ogg、Freight Display

**设计规则：**
- 极端的粗细对比是决定性的特征
- 细线衬线需要高分辨率再现——避免使用小尺寸或低分辨率屏幕
- 最适合标题和显示尺寸 - 不适用于正文
- 戏剧性源于规模：使用“大”以获得最大影响
- 与干净的无衬线字体搭配作为正文（经典时尚杂志公式）

**排版规范：**
````
类型分类： 现代 / Didone Serif
显示字体：[字体名称]
使用的粗细：[常规/粗体——更少的粗细，更多的戏剧性]
标题处理：[重量]、[大尺寸]、跟踪[宽]、[大写以获得最大戏剧性]
切勿用于：正文低于 18 像素、低分辨率屏幕、小字体
品牌个性搭配：奢华、戏剧性、时尚前卫、精致、编辑
最适合：时尚、美容、奢侈品、高端编辑、艺术和文化
搭配：[CLEAN SANS-SERIF for body——Vogue 公式]
````

