### 5.6 粗衬线

**它传达的信息：** 力量、信心、工业传统、大胆。厚重的块状衬线营造出坚固、接地气的效果。信号：建筑、制造、体育、媒体、骨干品牌。

**代表性字体：** Rockwell、Clarendon、Roboto Slab、Zilla Slab、Memphis、Archer

**设计规则：**
- 厚块衬线创造视觉稳定性和重量
- 粗笔画和细笔画之间的低对比度（比过渡更均匀）
- 以标题尺寸吸引注意力，以正文尺寸令人惊讶地可读
- 几何板（洛氏）感觉工业化；圆形板（Archer）感觉友好
- 与几何或怪诞的无衬线字体完美搭配

**排版规范：**
````
类型分类： 板衬线
主要字体：[字体名称]
使用的粗细：[浅色/常规/粗体/黑色]
标题处理：[重量]、[尺寸]、跟踪[值]
主体处理：[重量]、[尺寸]、线高[1.5-1.7]
子分类：【几何板 / 人文板 / 圆形板】
品牌个性匹配：坚强、自信、脚踏实地、实业、值得信赖
最适合：媒体、建筑、体育、政府、想要影响力和影响力的品牌
搭配：[GEOMETRIC SANS 带来干净的对比，HUMANIST SANS 带来温暖]
````

