### 5.7 显示/装饰版式

**它传达的信息：** 个性、独特、令人难忘的性格。显示字体专为大尺寸和短文本而设计——标题、徽标、海报、英雄时刻。他们为了影响力而牺牲了多功能性。

**设计规则：**
- 仅用于标题、徽标和英雄时刻 - 切勿用于正文
- 每个品牌系统一个显示面（更多会造成混乱）
- 展示面承载品牌个性；体面承载内容
- 确保显示面具有您的品牌需要的特殊字符
- 定制/修改的显示面创造最强的品牌所有权

**排版规范：**
````
类型分类: 展示/装饰
显示字体：[字体名称]
用途：仅限标题、英雄文本和品牌时刻
最大文本长度：[建议字数——通常为 3-8 个字]
最小尺寸：[SIZE——通常为 24px+ 或 18pt+]
它添加的品牌个性：[具体特征——复古/未来派/手工制作/野兽派/优雅]
切勿用于：正文、UI 标签、导航、法律文本、长段落
搭配：[干净可读的正文字体——总是需要作为平衡]
````

**AI图像提示--显示排版视觉：**
````
引人注目的显示版式样本，具有 [品牌名称] 的装饰字体 [字体名称]。一个由 3-5 个单词组成的强有力的标题，以戏剧性的超大尺寸呈现，展示了字体的独特特征和个性。字体具有[独特的特征——戏剧性的华丽/尖锐的几何切割/手绘纹理/复古造型]。在显示类型下方，干净的[BODY FONT] sans-serif 在一小段中演示了配对。个性丰富的展示面与干净的主体面之间的对比创造了完美的品牌排版层次。颜色：[品牌颜色]用于显示，中性用于主体。 4K、海报设计质量、排版前卫的编辑美学。
````

### 5.8 等宽字体

**它传达的信息：** 技术、代码、精度、原始数据、透明度。每个角色都占据相同的水平空间，创造出严格的网格状节奏。信号：开发者文化、技术品牌、数据转发公司、透明度和诚实。

**代表性字体：** JetBrains Mono、IBM Plex Mono、Source Code Pro、Fira Code、Roboto Mono、SF Mono、Courier

**设计规则：**
- 相同的字符宽度在数据表和代码中创建自然对齐
- 阅读速度比比例字体慢——有意使用，而不是作为默认正文文本
- 创造“原始”或“未经过滤”的感觉——就像在展示源材料一样
- 非常适合数据显示、技术规格、定价表、时间戳
- 与人文主义或怪诞的无衬线字体搭配用于非数据内容

**排版规范：**
````
类型分类：等宽字体
单色字体：[字体名称]
用途：代码块、数据表、技术规范、原始数据显示、时间戳
它增加了品牌个性：技术精度、开发人员可信度、数据透明度
重量：[常规——通常使用单一重量]
大小：通常比比例正文小 1-2 像素
行高：[1.4-1.6——比比例文本更紧]
切勿用于：营销标题、情感文案、正文段落、UI 标签
配对：[所有非数据内容的比例无衬线]
````

**人工智能图像提示-等宽字体视觉效果：**
````
技术等宽排版样本，以 [品牌名称] 的 [字体名称] 为特色。显示屏显示类似代码的数据呈现，并带有完美对齐的文本列——定价表、技术规格或品牌领域的数据读数。刚性的字符网格营造出一种精确和透明的感觉。语法突出显示的代码块示例显示了其自然栖息地的字体。与周围的正文文本搭配干净的 [SANS-SERIF]，在“原始数据”和“人类叙述”之间形成对比。颜色：[品牌颜色] 用于语法突出显示重音符号，浅灰色或深色背景用于代码块。 4K、开发人员文档质量、GitHub/Stripe 技术美学。
````

### 5.9 类型配对规则

将两种（最多三种）字体组合成一个连贯系统的艺术和科学。糟糕的搭配甚至会破坏最好的字体选择。

**基本配对原则：**
````
类型配对规则

规则 1：对比，而非冲突
这对字体在结构上明显不同，但有一个无形的质量线索。
好：Didone 衬线标题 + 几何无正文（最大对比度，两者都精确）
不好：两种不同的几何无衬线字体（太相似，会造成混乱）

规则 2：一种性格，一种主力
显示/标题面带来个性。体面带来可读性。
永远不要让两种字体争夺注意力。

规则 3：匹配 X 高度
当两种字体彼此靠近时（尤其是在同一行中），相似的 x 高度会产生视觉和谐。
相同点大小的不同 x 高度看起来不匹配。

规则 4：最多两个家庭（如果包含 Mono，则为三个）
主要：头条新闻、品牌时刻、导航
次要：正文、UI 文本、标题
可选：等宽字体用于数据/代码

规则 5：分类对比
跨分类边界的最佳配对：
- Serif + Sans-serif（经典）
- 显示+中性（个性+可读性）
- 几何+人文（精准+温暖）

经过验证的配对：
- Playfair Display + Source Sans Pro（编辑优雅+清晰可读）
- Montserrat + Merriweather（几何现代+温暖易读的衬线）
- 奥斯瓦尔德+拉托（凝聚冲击力+友善的身体）
- Roboto Slab + Roboto（同一家族，不同分类）
- Futura + Garamond（几何精度+古典优雅）
- Inter + Libre Baskerville（瑞士中立+社论衬线）
- DM Sans + DM Serif Display（匹配设计DNA，不同分类）
````

### 5.10 版式层次系统

完整的层次结构系统定义了每个级别的文本如何与其他级别相关。如果没有等级制度，所有文本都会平等竞争，没有什么能脱颖而出。

**层次结构规范：**
````
排版层次系统

1 级——英雄/展示（吸引注意力，谨慎使用）
字体：[显示字体]
尺寸：48-96px（网页）/36-72pt（印刷）
重量：[粗体/黑色]
追踪：[请注明]
大小写：[大写/标题大小写]
颜色: [主要品牌颜色]
用途：英雄部分、活动标题、封面

2 级——H1/页面标题（主要内容标题）
字体：[主要字体]
尺寸：32-48px（网页）/24-36pt（印刷）
重量：[粗体]
追踪：[请注明]
线高：1.1-1.2
颜色：[原色或近黑色]
用途：页面标题、章节标题、文章标题

3 级——H2/章节标题（二级结构）
字体：[主要字体]
尺寸：24-32px（网页）/18-24pt（印刷）
粗细：[半粗体/中粗体]
追踪：[请注明]
线高：1.2-1.3
颜色：[原色或深灰色]
用法：章节标题、卡片标题、分段符

4 级——H3/小节（三级结构）
字体：[主要字体]
尺寸：20-24px（网页）/14-18pt（印刷）
重量：[中]
线高：1.3-1.4
颜色: [深灰色]
用途：小节标题、功能标题、侧边栏标题

5 级——正文/段落（主要阅读文本）
字体：[正文字体]
尺寸：16-18px（网页）/10-12pt（印刷）
重量：[常规]
线高：1.5-1.7
跟踪：[0 到 +10]
颜色：[近黑色 -- #1A1A1A 至 #333333]
最大行长度：65-75 个字符，以获得最佳可读性
用法：段落、描述、长格式内容

6 级——小/标题（支持文本）
字体：[正文字体]
尺寸：12-14px（网页）/8-10pt（印刷）
重量：[常规或中号]
线高：1.4-1.5
颜色：[中灰色 -- #666666 至 #888888]
大小写：[句子大小写或标签大写]
用途：标题、脚注、元数据、时间戳、标签

7 级——上线/眉毛（类别标签、小写字母）
字体：[主要字体或正文字体]
尺寸：11-13px（网页）/8-9pt（印刷）
粗细：[半粗体/粗体]
跟踪：[WIDE -- +100 至 +200]
案例：[大写]
颜色：[品牌颜色或中灰色]
用途：类别标签、节眉、标签标签
````

**AI图像提示-排版层次视觉：**
````
[BRAND NAME] 品牌指南的专业排版层次样本。干净的垂直布局显示所有 7 个层次结构级别从最大到最小堆叠。 Hero 在 [DISPLAY FONT] 中在顶部显示文本，然后在 [BODY FONT] 中通过正文文本显示 H1 到标题大小。每个级别都清楚地标有字体名称、大小、粗细和跟踪值。一致的左对齐创建清晰的基线网格。从戏剧性的显示到安静的标题的进展展示了类型系统的全部范围。颜色：显示级别为[品牌颜色]，正文文本过渡为深灰色。干净的白色背景，层次之间的间距很大。 4K，专业品牌指引品质，类型系统文档美观。
````

---

## 模块 6：视觉元素和模式——可拥有的图形设备

除了徽标、颜色和类型之外，品牌还需要一个可拥有的图形元素库，以在每个接触点上创建视觉一致性。这些都是让品牌系统感觉完整且独特的配角。

### 6.1 几何图案

**它传达的信息：** 秩序、精确、数学之美。几何图案创造节奏和结构。它们标志着重视逻辑、清晰和系统思维的品牌。

**设计规则：**
- 从徽标或品牌标记中导出图案几何形状（确保视觉 DNA 一致性）
- 定义可以无限缩放的重复单元（图块）
- 将图案颜色限制为品牌调色板——切勿引入新颜色
- 以降低背景不透明度 (10-20%) 的方式使用；全力应对重音时刻
- 定义图案单元的最小和最大比例

**模式规范框架：**
````
图案系统：几何
底座形状：[CIRCLE / TRIANGLE / SQUARE / HEXAGON / CUSTOM——源自标志]
重复类型：[网格/砖块/径向/对角线/随机]
单位尺寸：[DIMENSION]重复
颜色：[图案中使用的品牌颜色]
不透明度范围：[背景 10-20%，重点 50-100%]
比例范围：[最小单位尺寸]��[最大单位尺寸]
旋转：[固定/45 度/90 度变化]
应用：背景、分区、包装填充、演示幻灯片
````

**AI图像提示——几何图案品牌视觉：**
````
[品牌] 的复杂几何图案设计。使用源自品牌视觉语言的[BASE SHAPE]无缝重复图案。在[背景颜色]上以[品牌颜色]呈现的图案。几何形状精确且数学化，每个单元完美对齐以创造更大的视觉节奏。以三种比例显示图案：宏观视图（完整图案覆盖）、中度视图（图案作为内容背后的背景）和特写细节视图（单个单元构造）。干净的矢量精度，没有手绘缺陷。这种图案给人一种拥有感和独特的品牌感。 4K、纺织/表面设计质量、优质图案呈现。
````

### 6.2 有机/流体形状

**它传达的信息：** 人性、创造力、自然温暖、平易近人。有机形状打破了几何系统的僵化，增加了生命力和动感。最适合那些想要感受到活力、创造力或与自然联系的品牌。

**设计规则：**
- 创建一个包含 5-8 个主形状的库，定义有机词汇
- 形状应该是故意的，而不是随机的（受控有机）
- 用作容器、分区分隔符、图像蒙版或背景元素
- 确保形状在不同比例下工作而不会失去特征
- 结合几何类型和网格，产生张力和趣味

**模式规范框架：**
````
有机形状系统：
形状词汇：[BLOB / WAVE / FLOW / TERRAIN / BOTANICAL / LIQUID]
主形状数量：[5-8个定义形状]
曲线质量：[平滑/角度有机/绘画]
颜色处理：[纯色/渐变/半透明]
比例范围：[小重音到全出血背景]
与网格交互：[重叠/包含/打破边界]
应用：图像蒙版、部分背景、装饰口音、社交媒体
````

**AI图像提示——有机形状品牌视觉：**
````
[品牌] 的流体有机形状系统。 [品牌颜色] 中的 [NUMBER] 个流畅形状的集合，每个形状都具有独特的特征，但共享相同的视觉 DNA - 相似的曲线质量、重量和能量。形状单独显示在干净的网格上，然后在应用程序中演示：作为图像蒙版、背景元素和部分分隔符。这些形状感觉自然而生动，就像在运动中捕捉到的流体一样。 [颜色处理——实心填充/软渐变/半透明覆盖]。白色背景上的干净演示文稿，并标记了每个形状。 4K、图形设计系统品质、现代品牌美学。
````

### 6.3 线路系统

**它传达的信息：** 结构、方向、联系。线条创造视觉路径，分隔内容，并在没有重量的情况下增加节奏。从细线规则到大胆的笔触，线条是最通用的图形元素。

**设计规则：**
- 使用特定的像素/点值定义线宽（细线、浅线、中线、粗体）
- 线条风格：实线、虚线、点线——每种都有不同的个性
- 方向线暗示运动；水平线表明稳定
- 使用线条在相关内容之间创建视觉联系
- 颜色：通常为品牌原色或中性灰色；强调颜色

**线路系统规格：**
````
线路系统：
Hairline: [0.5-1px] -- 微妙的分隔线，表格规则
Light: [1-2px] -- 部分分隔符、卡片边框
Medium: [3-4px] -- 强调下划线，活动指示器
粗体：[6-8px]——品牌重音笔画、装饰条
超粗体：[12-16px]——英雄元素，戏剧性的口音
样式选项：实线/虚线/点线
颜色：[品牌主色]、[中性灰色]、[强调色]
帽子款式：[扁/圆/方]
连接方式：[斜接/圆形/斜角]
应用：分隔线、下划线、边框、装饰元素、数据可视化轴
````

**AI图像提示——线路系统品牌视觉：**
````
[品牌] 的清洁生产线系统设计。技术规格显示从细线到超粗体的五种线宽，每种线宽均采用 [品牌颜色] 和 [中性]。线条样式演示：每个粗细的实线、虚线、点线。应用示例：线条作为布局中的部分分隔符、标题上的下划线强调、卡片上的边框处理以及装饰性图形元素。线条系统在不增加视觉重量的情况下创造了节奏��结构。带有注释的白色背景上的清晰精确演示。4K、设计系统文档质量、瑞士平面设计精度。
````

### 6.4 纹理和材质

**它传达的信息：** 触觉品质、深度、工艺、感官丰富度。纹理为数字品牌增添了物理维度，创造了真实材料和表面的印象。

**设计规则：**
- 定义 2-3 个与品牌个性相符的主要纹理
- 对背景使用低不透明度 (5-15%)，对特色时刻使用较高不透明度
- 纹理不得影响文本可读性
- 考虑打印复制：某些纹理在屏幕上有效，但在打印时失败
- 材料参考：纸纹、织物、混凝土、木材、金属、大理石

**纹理规格：**
````
纹理系统：
主要材质：[材质--纸纹/混凝土/亚麻/拉丝金属/大理石]
  应用：主要背景、英雄部分、特色内容区域
  不透明度范围：[细微5-15%，突出30-50%]
二级纹理：[材质]
  应用：卡片、容器、辅助表面
  不透明度范围：[5-10%]
强调纹理：[材质]
  应用：特殊时刻、优质接触点
颜色交互：纹理[MULTIPLIED / OVERLAID / SCREEN]与品牌颜色
印刷规格：[SPOT UV / EMBOSS / DEBOSS / FOIL / TEXTURED STOCK]
````

**AI图像提示——质感品牌视觉：**
````
[品牌] 的触觉纹理系统。按比例显示三种材质纹理：[主要纹理]、[次要纹理] 和 [强调纹理]。每个纹理都在三种应用中展示：作为文本后面的微妙背景（低不透明度）、作为特色表面（中等不透明度）以及作为显示材质质量的特写细节。采用[品牌颜色]着色处理呈现的纹理。这些纹理为数字品牌增添了物理尺寸和工艺质量。下图：打印规格模型显示了名片上纹理的[打印技术 - 局部 UV/浮雕/箔]应用。 4K、表面设计品质、优质材质美感。
````

### 6.5 图像风格

**它传达的信息：** 功能清晰，小空间内品牌一致性。图标是品牌的视觉速记——它们必须能够立即被理解，同时在微小的尺寸下保持品牌个性。

**设计规则：**
- 所有图标均构建在一致的网格上（通常为 24x24 或 32x32 基础）
- 笔画粗细与品牌排版粗细关系相匹配
- 所有图标的角半径一致（尖锐、略圆或全圆）
- 光学对齐：图标必须看起来居中，而不仅仅是数学上居中
- 样式类别：轮廓、填充、双色调或立体

**图像规范：**
````
图标系统：
网格：[SIZE]x[SIZE]px 基础网格，带有 [PADDING]px 安全区域
笔画粗细：[WEIGHT]px（匹配[BODY FONT]视觉粗细）
角半径：[VALUE]px（匹配 UI 组件半径）
风格：[轮廓/填充/双色调/立体]
帽子：[圆形/扁平]
连接：[圆形/斜接]
颜色：【单色——品牌主色或中性色】
最小尺寸：[SIZE]px（低于此，切换到简化版本）
隐喻规则：[通用——避免特定文化的符号]
一致性检查：所有图标必须通过“眯眼测试”——模糊时可识别
````

**AI图像提示——形象品牌视觉：**
````
[品牌] 的专业图标系统。 16-20 个图标网格，涵盖常用功能（主页、搜索、设置、个人资料、通知、消息、共享、下载、心形、购物车、菜单、关闭、箭头、检查、加号、过滤器）。所有图标均构建在一致的 [SIZE]px 网格上，并具有 [STROKE WEIGHT]px 笔划。 [风格——轮廓/填充/双色调]处理采用[品牌颜色]。所有图标的 [CORNER RADIUS] 角半径一致。每个图标都有自己的网格单元，构造线依稀可见。图标集感觉就像一个有凝聚力的家庭——相同的 DNA，不同的表达。干净的白色背景，有组织的网格布局。 4K、设计系统质量、材料/SF 符号精度。
````

### 6.6 插画风格

**它传达的信息：** 个性、讲故事的能力、视觉解释。插图将品牌的声音延伸到摄影无法实现的视觉叙事中——抽象概念、未来愿景、有趣的时刻。

**设计规则：**
- 定义单一插图风格（不要在品牌系统内混合风格）
- 插图风格必须与摄影相辅相成，而不是与之竞争
- 创建角色一致性：如果人类出现，定义身体比例、特征、多样性
- 调色板必须与品牌颜色完全匹配
- 定义复杂程度：简单的点插图、中等的社论、复杂的英雄

**插图规格：**
````
插画系统：
风格：[平面矢量/线条艺术/等距/3D渲染/手绘/拼贴]
线条质量：[CLEAN VECTOR / HAND-DRAWN / BRUSH / PENCIL]
颜色方法：[全品牌调色板/限量3色/单色]
人物：[真实比例/风格化/抽象/无]
多样性：[肤色/体型/年龄范围/能力表现]
详细程度：
  现货插图：简单、概念单一、图标式
  编辑插图：中等细节、基于场景、支持文本英雄插画：复杂、全场景、核心
背景处理：【透明/单色/环保】
动画就绪：[是——设计时考虑到运动/否——仅静态]
````

**AI图像提示——插画风格视觉效果：**
````
[BRAND NAME] 的品牌插画风格指南。 [风格] 插图显示[场景/概念]。 [线条质量] 线条采用 [品牌颜色]。 【人物造型】人物形象多样，表现形式多样。并排展示了三个复杂程度：现场插图（简单，小型），社论插图（中，支持）和英雄插图（复杂，特色）。所有��个关卡都具有相同的视觉 DNA——一致的线宽、调色板和字符风格。这些插图给人一种明显的品牌感——你可以遮住徽标，但仍然知道这个品牌。白色背景上的干净演示。 4K，专业插画品质，品牌指引审美。
````

### 6.7 数据可视化风格

**它传达的信息：** 可信度、透明度、智慧。品牌如何呈现数据反映了其与事实的关系以及对受众智慧的尊重。

**设计规则：**
- 仅来自品牌调色板的图表颜色——创建特定的数据颜色序列
- 定义主要数据颜色、次要数据颜色、第三数据颜色和强调/突出显示颜色
- 网格线和轴：使用最轻的中性线，从不与数据竞争
- 标签：品牌正文字体与标题大小一致，定位一致
- 辅助功能：颜色对于色盲用户来说必须是可区分的；添加模式作为后备

**数据可视化规范：**
````
数据可视化风格：
数据颜色顺序：[颜色 1 主数据]、[颜色 2]、[颜色 3]、[颜色 4]、[颜色 5]
强调色：[强调色——用于突出显示的数据点]
负面/危险：[红色变体]
积极/成功：[绿色变体]
网格线颜色：[最浅中性 - #E0E0E0 或类似]
轴颜色：[中性]
标签字体：[BODY FONT]、[SIZE]、[COLOR]
定义的图表类型：条形图、折线图、饼图/圆环图、散点图、面积图、表格
条形上的角半径：[VALUE -- 匹配 UI 组件半径]
线宽：数据线为 [VALUE]px点/点大小：数据点为 [VALUE]px
注释样式：[CALLOUT/TOOLTIP 样式]
````

**AI图像提示--数据可视化品牌视觉：**
````
[品牌] 的专业数据可视化风格指南。四种图表类型（条形图、折线图、圆环图和数据表）均使用品牌数据调色板 [COLORS]。干净的现代图表设计，带有[正文字体]标签、浅灰色网格线和[品牌颜色]数据元素。一个数据点用 [强调色] 突出显示，以展示重点处理。图表排列在白色背景上的 2x2 网格中。所有图表类型的样式一致——相同的颜色、相同的字体、相同的网格处理。数据可视化感觉品牌化且专业。 4K、仪表板设计质量、Stripe/Bloomberg 数据美学。
````

### 6.8 模式应用规则

**应用图案、纹理和图形元素的设计规则：**
````
图案应用规则

1. 关注的层次
   图案是背景，而不是前景。如果图案与内容竞争，请降低其不透明度或将其删除。

2. 规模一致性
   定义 3 个标准图案比例：小（细节纹理）、中（部分背景）、大（英雄时刻）。切勿使用任意比例。

3. 色彩规则
   图案仅使用品牌颜色。减少至 1-2 种颜色以进行微妙的应用，完整的调色板以呈现英雄时刻。

4. 呼吸空间
   模式需要相邻的空白才能工作。充满每个表面的图案变成了壁纸——看不见且毫无意义。

5. 组合规则
   切勿将两种图案叠放。图案+纯色=好。图案+图案=视觉噪音。

6. 打印与打印数码
   以实际打印分辨率测试图案。 72dpi 的屏幕图案在 300dpi 打印时可能会出现摩尔纹或伪影。

7. 无障碍
   文本后面的图案必须保持 WCAG 对比度。如有疑问，请在图案和文本之间添加半透明覆盖层。

8. 文件格式
   图案图块：SVG 用于矢量，PNG 用于光栅。始终提供无缝的可平铺版本。包括 Figma/Sketch 组件版本。
````

