## 模块 7：布局和网格系统 -- 结构一致性

网格是将每个品牌传播联系在一起的无形架构。没有它，即使是美丽的元素也会陷入混乱。有了它，即使是简单的元素也会让人感觉有意而专业。

### 7.1 模块化网格

**它传达的信息：** 结构内的灵活性。模块化网格将页面划分为统一的矩形模块，这些模块可以以各种配置进行组合。信号：有组织的、通用的、系统的。

**设计规则：**
- 根据内容需求定义模块大小（文本块、图像、数据单元）
- 排水沟（模块之间的空间）必须始终保持一致
- 内容可以跨越多个模块，但必须与模块边界对齐
- 模块是原子单元——永远不要放置破坏模块边缘的内容

**网格规格：**
````
网格类型：模块化
模块：[COLUMNS]x[ROWS] 网格
模块尺寸：[WIDTH]x[HEIGHT] 单位
装订线：模块之间的[SIZE]（水平和垂直相等）
页边距：[SIZE] 页边距（上、下、左、右）
基线网格：[LINE-HEIGHT] 增量
内容规则：元素仅跨越整个模块——1x1、1x2、2x2、2x3 等。
断点（响应式）：
  桌面：[COLUMNS] 列，[GUTTER]px 装订线
  平板电脑：[COLUMNS] 列，[GUTTER]px 装订线
  移动设备：[COLUMNS] 列，[GUTTER]px 装订线
````

**AI图像提示--模块化网格布局：**
````
[品牌] 的专业模块化网格布局系统。干净的线框显示了 [COLUMNS]x[ROWS] 模块化网格，其中内容块跨越各种模块组合。网格线为浅蓝色，内容块为 [品牌颜色]，不透明度为 20%，关键内容区域突出显示。使用相同网格演示三种不同的页面组合——展示模块化灵活性如何在一致性中创造多样性。显示边距、装���线和模块尺寸的注释。白色背景上干净的技术绘图风格。4K，设计系统文档质量。
````

### 7.2 列网格

**它传达的信息：** 编辑结构、内容层次结构。列网格垂直划分页面，为文本流和图像放置创建通道。编辑设计、网页布局和多内容页面的标准。

**设计规则：**
- 常用列数：4 列（简单）、6 列（灵活）、12 列（最大灵活性）
- 12 列网格允许细分为 2、3、4、6——最通用的选择
- 按列跨度定义的内容区域（例如，主要内容 8 列，侧边栏 4 列）
- 悬挂缩进和拉引号可以打破列边界以强调
- 在所有断点处保持一致的边距和装订线

**网格规格：**
````
网格类型：列
列：[数字 - 建议 6 或 12]
列宽：[FLUID/FIXED -- 指定 px 或 %]
装订线：[SIZE]px
页边距：[SIZE]px（左/右页边距）
最大内容宽度：[SIZE]px（防止大屏幕上的线条过宽）
常见布局：
  全角：[ALL] 列
  三分之二+侧边栏：[8+4]或[9+3]列
  一半+一半：[6+6]列
  三等：[4+4+4]列
  不对称：[5+7] 或 [7+5] 列
````

**AI图像提示--列网格布局：**
````
[品牌] 的专业柱网格系统。干净的线框显示了 [NUMBER] 列网格，其中多个布局变体垂直堆叠在同一页面上。顶部：跨越所有列的全角英雄。中：三分之二的内容区域加上侧边栏。底部：三列相等的卡片或功能。网格线以浅蓝色可见，内容块以低不透明度的[品牌颜色]显示。已注释边距和装订线尺寸。并排显示响应式断点比较：台式机、平板电脑、移动设备。4K、设计系统文档质量、蓝图 CSS 美学。
````

### 7.3 分层网格

**它传达的信息：** 动态的编辑活力、杂志品质的布局。分层网格通过不同的元素大小优先考虑内容的重要性，打破了视觉叙事的严格列对齐。

**设计规则：**
- 最大的元素受到最多的视觉重量和关注
- 大小差异应该很大（级别之间的比例至少为 2:1）
- 即使没有严格的列，也保持一致的边距和基线对齐
- 使用松散的底层网格，但允许特色内容打破它
- 最适合编辑跨页、登陆页面和作品集布局

**网格规格：**
````
网格类型：分层
基础网格：[用于对齐参考的松散列网格]
特征尺寸：
  英雄：[页面比例 -- 60-70%]
  次要：[比例 -- 25-30%]
  第三：[比例 -- 10-15%]
级别之间的比例：[最小 2:1]
对齐规则：[MARGINS始终一致，文本的BASELINE GRID]
打破规则：[哪些元素可以打破网格，何时]
````

**AI图像提示--分层网格布局：**
````
[品牌名称] 的动态分层布局。编辑质量的页面设计，一个主要的英雄图像或内容块占据布局的 60%，并由 25% 的二级元素和小型三级元素支持。布局给人一种杂志社论的感觉——戏剧性的尺寸对比创造了清晰的视觉层次。 [品牌颜色] 中的内容块具有不同的不透明度。底层网格线若隐若现，展现出灵活的结构逻辑。注释突出显示有意的尺寸比率。4K、编辑设计质量、《Vogue》/《彭博商业周刊》版面能量。
````

### 7.4 稿件网格

**它传达的信息：** 专注、简单、经典的阅读体验。具有宽边距的单列文本。最古老、最简单的网格，非常适合长篇阅读、信件格式和重点内容。

**设计规则：**
- 单文本栏，各边都有大量边距
- 最佳行长：65-75 个字符，阅读舒适
- 边距创建框架——它们是设计元素
- 放置在页边空白处的连续标题、页码和脚注
- 最适合书籍、文章、信件、报告、单栏文档

**网格规格：**
````
网格类型：手稿
文本列宽度：[SIZE - 正文大小为 65-75 个字符]
页边距：顶部 [SIZE]、底部 [SIZE]、内部 [SIZE]、外部 [SIZE]
  传统比例：内 < 上 < 外 < 下（金典）
  现代比例：四周边距均等（干净、最小）
边距内容：[运行标题/页码/脚注/引用]
基线网格：[正文的行高]
````

**AI图像提示--稿件网格布局：**
````
[品牌名称] 的经典手稿网格布局。优雅的单栏文本布局，内容边框宽大。 [SERIF/SANS-SERIF] 正文采用舒适的阅读尺寸，每行 65-75 个字符。利润丰厚，顶部有小写字母的连续标题。页码位于下边距。一个引述插入外部边缘以强调。布局感觉就像排版精美的书页——专注、平静、尊重读者的注意力。温暖的灰白色背景，深色文字。4K、书籍设计品质、凸版出版美学。
````

### 7.5 响应式网格系统

**它传达的信息：** 现代、设备感知、以用户为中心。响应式网格可适应不同屏幕尺寸的内容结构，从而保持从桌面到移动设备的品牌一致性。

**设计规则：**
- 定义断点：移动设备 (320-767px)、平板电脑 (768-1023px)、桌面 (1024px+)、大型 (1440px+)
- 内容重排，而不仅仅是缩小——布局在每个断点处发生变化
- 触摸目标：移动设备上最小 44x44 像素 (Apple HIG)
- 版式按比例缩小，但地板尺寸最小
- 图像：在每个断点进行艺术指导，而不仅仅是裁剪中心

**响应规范：**
````
响应式网格系统：
移动设备 (320-767px)：[4] 列，[16]px 装订线，[16]px 边距
  排版比例：主体 16 像素，H1 28 像素，H2 22 像素
  触摸目标最小：44x44px
  堆栈顺序：[VERTICAL STACK -- 单列]

平板电脑 (768-1023px)：[8] 列，[20]px 装订线，[24]px 边距
  排版比例：主体 16 像素，H1 36 像素，H2 26 像素
  布局：[灵活 - 适当时为 2 列]

桌面 (1024-1439px)：[12] 列，[24]px 装订线，[32]px 边距
  排版比例：主体 18 像素，H1 48 像素，H2 32 像素
  最大内容宽度：[1200]px

大 (1440px+)：[12] 列，[32]px 装订线，[AUTO]px 边距（居中）
  排版比例：主体 18 像素，H1 56 像素，H2 36 像素
  最大内容宽度：[1440]px
````

**AI图像提示--响应式网格视觉：**
````
[品牌] 的专业响应式网格系统。从左到右排列的四个设备框架：手机、平板电脑、笔记本电脑、台式显示器。每个中显示相同的内容，网格明显适应：移动设备上 4 列（单列堆栈），平板电脑上 8 列（2 列布局），桌面和大屏幕上 12 列（完整多列）。网格线为浅蓝色，内容块为[品牌颜色]。显示断点值、装订线大小和边距变化的注释。内容会智能地转换——不仅仅是缩小，而是针对每个设备进行重新组织。 4K、响应式设计文档质量、现代 UI 框架美学。
````

### 7.6 空白哲学

**它传达的信息：** 自信、清晰、奢华的空间。空白（负空间）并不是“空的”——它是一种活跃的设计元素，为内容提供呼吸的空间，并通过空间关系创建视觉层次结构。

**设计规则：**
- 空白与品牌定位成正比：豪华=更多空间，价值=更少空间
- 微小的空白（字母、线条、元素之间）创造了可读性
- 宏观空白（边距、分节符、页边距）创建层次结构和呼吸空间
- 一致的间距单位：定义基本单位（常见的是 8px）并使用倍数
- 徽标周围的空白是不可协商的（参见模块 3.9）

**空白规范：**
````
空白系统：
底座间距单位：[8]px
间距比例：[8, 16, 24, 32, 48, 64, 96, 128]px
微空间（组件内）：[8-16]px
细观空间（组件之间）：[24-48]px
宏观空间（部分之间）：[64-128]px
页边距：[最小边距——通常为页面宽度的 5-10%]
部分填充：[顶部/底部填充值]
内容密度：[AIRY / BALANCED / DENSE——基于品牌定位]
规则：如有疑问，请添加更多空间，而不是更少
````

### 7.7 视觉层次规则

通过大小、重量、颜色和空间关系来引导注意力的系统。

**层次结构规范：**
````
视觉层次规则

1. 尺寸：较大的元素首先吸引注意力
   层级之间的比例：最小 1.5:1

2. 重量：较大胆的元素先于较轻的元素吸引注意力
   定义粗细级数：浅色 -> 常规 -> 中等 -> 粗体 -> 黑色

3、颜色：饱和/暖色进阶；柔和/冷色退去
   品牌主要用于强调，中性用于支持内容

4.对比度：高对比度=高关注度，低对比度=背景
   每个 WCAG 的可访问性的最低对比度

5. 位置：左上角（LTR 文化）首先受到关注（F 模式阅读）
   第一屏/折叠中的关键内容，下面的支持内容

6. 隔离：被空白包围=很重要
   元素周围的空间越大=感知的重要性越高

7. 方向：眼睛追随线条、箭头和方向提示
   使用构图引导视线：初级->次级->CTA

申请顺序：
设计任何布局时，请按以下顺序应用层次结构：
1. 最重要的一个因素是什么？使其最大且对比度最高。
2.什么是第二？让它明显变小但仍然突出。
3. 号召性用语是什么？赋予它强调色和隔离性。
4. 其他一切都是支撑性的——减少其视觉重量直至其消退。
````

---

## 模块 8：摄影与图像风格 -- 视觉叙事标准

摄影是任何品牌系统中最直接的情感元素。在眼睛处理徽标或阅读文本之前，它已经吸收了图像传达的情绪、质量和个性。

### 8.1 社论/生活方式摄影

**它传达的信息：** 抱负、真实性、一种生活方式。编辑摄影讲述了有关品牌世界的故事——体现其价值观的人物、地点和时刻。

**设计规则：**
- 自然或自然主义照明（非单间公寓）；黄金时刻和窗光都是经典
- 拍摄对象捕捉到真实的瞬间，而不是僵硬的姿势
- 环境与主题一样讲述故事
- 颜色分级必须与品牌调色板相匹配（暖色、冷色、中性——定义它）
- 景深在图像内创建焦点层次结构

**摄影规格：**
````
摄影风格：社论/生活方式
灯光：自然/自然主义--[暖金色/冷扩散/戏剧性方向]
色温：[暖色 3200K / 中性 5000K / 冷色 6500K]
颜色等级：[WARM EARTH / COOL DESATURATED / NEUTRAL BALANCED / FILM EMULATION -- 指定库存]
对象行为：坦率、真实、不做作——捕捉真实瞬间
环境角色：[配角——讲述故事/最小——聚焦主题]
景深：[浅 -- f/1.4-2.8 / 中 -- f/4-5.6 / 深 -- f/8-11]长宽比：[16:9 / 4:3 / 3:2 / 1:1 / 垂直 9:16]
后期制作：[极简——真实场景/中度——增强情绪/重——风格化]
禁止：库存照片陈词滥调（强迫微笑、握手、指着屏幕）
````

**人工智能图像提示——编辑生活摄影：**
````
[行业] 公司[品牌] 的编辑生活方式照片。 [环境] 中的[主题]，捕捉到[动作/情感] 中真实的、不摆姿势的时刻。 [灯光——温暖的黄金时段/柔和的窗光/凉爽的阴天扩散]。 [颜色等级 - 柯达 Portra 暖色调/富士 Pro400H 冷色调/中性平衡]。浅景深 (f/2.0)，拍摄对象清晰对焦，环境柔和模糊。构图遵循三分法并带有[主题位置]。该图片讲述了一个关于[品牌价值/生活方式]的故事。没有强迫的姿势，没有库存照片中的微笑。胶片颗粒纹理为 10%，可实现模拟温暖效果。 [长宽比]。使用 35mm 等效镜头拍摄，编辑摄影质量，[杂志参考 - Kinfolk/Cereal/Monocle] 美学。
````

### 8.2 产品摄影

**它传达的信息：** 质量、细节、需求。产品摄影必须让产品成为主角——每个细节、纹理和表面处理都清晰可见、美丽动人。

**设计规则：**
- 两种模式：工作室（干净、受控）和情境（自然环境中的产品）
- 工作室：一致的照明设置，明确的背景（白色、灰色、黑色或品牌颜色）
- 情境：产品风格符合理想的环境，并配有互补的道具
- 阴影处理：硬阴影（现代、图形）与软阴影（自然、高级）
- 后期制作一致性：所有产品镜头的曝光、白平衡和颜色等级相同

**摄影规格：**
````
摄影风格：产品
演播室设置：[背景颜色]背景，带[照明——柔光箱/边缘光/平光/戏剧]
阴影样式：[硬接触/软扩散/浮动/无（纯抠图）]
角度定义：
  Hero：[3/4 视角/直视/自上而下/低角度]
  细节：[特写显示材料/纹理/饰面]
  比��：[用人手或上下文物体作为尺寸参考]
  组：[多种产品排列显示范围/系列]
情境设置：【环境——自然使用产品的生活方式场景】颜色准确性：[重要 - 产品颜色必须与 Delta-E 3 内的实际产品相匹配]
修饰级别：[最小——忠实于产品/清洁——去除灰尘/瑕疵/增强——理想化]
````

**AI图像提示--产品摄影：**
````
[品牌] 的 [产品] 的优质产品摄影。 [拍摄类型——英雄 3/4 角度/自上而下平躺/特写细节]。 [背景——干净的白色无限海湾/深色喜怒无常的背景/品牌颜色背景/生活方式背景]。 [照明——柔和的漫射演播室光/戏剧性的边缘照明/自然窗户光]。 [阴影风格--柔和的自然阴影/坚硬的图形阴影/浮动无阴影]。每个材料细节都可见 - [材料细节 - 拉丝金属纹理/哑光柔软触感表面/玻璃反射/织物编织]。色彩准确的再现。框架中带有[品牌颜色]强调元素的构图。如果上下文有样式道具：[补充对象]。使用等效中画幅 f/8 拍摄以获得最大清晰度。 4K、商业产品摄影品质、Apple/Dyson 产品页面美观。
````

### 8.3 环境/建筑摄影

**它传达的信息：** 规模、存在、品牌所处的物理世界。环境摄影确立了品牌的空间特征——办公室、商店、景观和建筑。

**设计规则：**
- 垂直线必须是真正垂直的（正确的透视变形）
- 自然光优先；室内建筑照明
- 人员存在可选——当包括在内时，人员提供规模，而不是焦点
- 一天中的时间是一个创造性的选择：黄金时段温暖，蓝色时段戏剧，中午清晰
- 广角但不变形； 24-35mm等效是最佳点

**摄影规格：**
````
摄影风格：环境/建筑
镜头：【24-35mm等效——宽但不失真】
视角：[必须纠正垂直方向]
照明：[自然日光/黄金时段/蓝色时段/室内建筑]
一天中的时间：[指定或灵活]
人类存在：[无/尺度参考/附带/生活方式整合]
颜色等级��[建筑中性/温暖内饰/酷现代/电影模拟]
后期制作：[透视校正/HDR 混合/天空替换政策]
构图：[对称/引导线/三分法]```

**AI图像提示--环境摄影：**
````
[品牌名称] 的建筑环境照片。 [建筑/空间类型] 使用正确的垂直线和清晰的视角拍摄。 【LENS——28mm广角】展现完整的空间脉络。 [照明——黄金时段温暖的光线投射出长长的阴影/蓝色时段凉爽的环境/明亮的正午清晰度]。 [人类元素——提供比例的小人物/强调建筑的空白空间]。干净的[颜色等级——暖色/冷色/中性]后期制作。强大的几何构图——[引导线/对称/三分法则]。该空间传达[品牌价值——创新/传统/开放/优质]。建筑摄影品质，垂直直线，无桶形失真。 4K、ArchDaily/Dezeen 出版物质量。
````

### 8.4 肖像/人物摄影

**它传达的信息：** 人际关系、多样性、品牌背后的面孔。肖像摄影必须尊重真实的人物，同时保持品牌一致性。

**设计规则：**
- 真实的表达胜过完美的姿势
- 爆头的一致照明设置（确保所有团队照片匹配）
- 多样性：代表品牌所服务的实际社区
- 修饰政策：正确的曝光和色彩，保留皮肤纹理和自然特征
- 背景一致性：中性色、品牌色或环保色（选择其中之一并提交）

**摄影规格：**
````
摄影风格：肖像/人物
灯光设置：[伦勃朗/蝴蝶/循环/广阔/自然窗]
背景：[中性灰色/白色/品牌颜色/环境色——整个系列一致]
表情方向：[自然微笑/体贴/直视/坦诚]
取景：[近距头像/头部和肩部/环境肖像/全身]
修饰：【保留自然特征——正确曝光，仅去除暂时性瑕疵，保持肤质��不整形】多样性：[代表——年龄范围、种族、性别、体型、能力]
颜色等级：[一组中所有肖像均一致]
````

**AI图像提示--人像摄影：**
````
[品牌名称] 的真实肖像照片。 [主题描述] 具有[表达——真诚温暖的微笑/深思熟虑的直视/坦诚的对话]表情。 [灯光——柔和的伦勃朗灯光/明亮的蝴蝶灯光/自然窗户光]创造出讨人喜欢但诚实的照明。 [背景——干净的中性灰色/品牌颜色背景/环境背景]。头肩顶框架带有[组合注释]。保留自然肌肤纹理，暖色调匹配品牌摄影系统。这幅肖像给人一种真实、人性化的感觉，而不是公司的库存照片。使用 85 毫米等效人像镜头、f/2.8 拍摄，[品牌颜色] 巧妙地出现在衣柜或背景中。 4K、编辑肖像画质，真实而温馨。
````

### 8.5 抽象/观念摄影

**它传达的信息：** 创造力、智力深度、视觉隐喻。抽象摄影通过视觉象征而不是字面描述来表达品牌概念。

**设计规则：**
- 每个抽象图像必须有明确的概念意图（不是随机的）
- 品牌颜色必须出现在调色板中或在调色板中引用
- 在整个集合中保持一致的抽象风格
- 用于英雄背景、编辑插图、概念活动
- 抽象级别：稍微抽象（可识别的主题）到完全抽象（纯粹的形式/颜色）

**摄影规格：**
````
摄影风格：抽象/概念
抽象级别：[轻微--可识别的主题/中等--建议的形式/完全--纯颜色和形式]
技术：[微距/运动模糊/多重曝光/光绘/反射/折射]
颜色：[品牌调色板映射 - 特定角色的特定颜色]
质地：[光滑/有机/几何/液体/晶体]
心情：[精力充沛/沉思/神秘/快乐/宁静]
用法：[英雄背景/社论/社交媒体/演示/物理安装]
````

**AI图像提示——抽象品牌摄影：**
````
[品牌名称] 的抽象概念照片。 [技术——自然形态的宏观特写/透过玻璃的光折射/冻结在运动中的流体动力学/几何阴影图案]。颜色精确映射到品牌调色板：[颜色 A] 占主导地位，[颜色 B] 为重点。 [质地] 品质贯穿始终。抽象暗示[概念/隐喻——成长/联系/转变/创新]，但没有文字描述。通过[照明质量]营造的[气氛]氛围。适合用作带有 [DARK/LIGHT] 叠加层的文本后面的英雄背景。高分辨率，关键细节清晰，大气深度。 4K、美术摄影品质、概念性战役美学。
````

### 8.6 颜色分级和后期制作

定义后期制作外观，使所有品牌摄影感觉有凝聚力，无论摄影师或拍摄条件如何。

**颜色分级规格：**
````
颜色分级标准

曝光：[目标——通风稍高/中性为正中心/喜怒无常]
白平衡：[暖色 +200K / 中性 / 冷色 -200K 真白]
对比度：[低代表电影效果/中代表自然/高代表图形效果]
饱和度：[去饱和 80% 实现编辑平静/自然 100%/增强 120% 实现能量]
亮点：[WARM ROLLOFF - 奶油色/金色/COOL ROLLOFF - 蓝色/中性]
阴影：[提升 - 用于电影外观（添加 5-10% 黑点）/粉碎 - 用于戏剧/中性]
肤色：[受保护——肤色排除在重分级之外，保持自然温暖]胶片模拟：[具体说明 -- Kodak Portra 400 / Fuji Pro 400H / Kodak Ektar / 无]

禁用效果：
- 大量 HDR 处理
- 极度清晰度/结构增强
- 交叉加工（除非明确定义为品牌风格）
- 可选颜色（除一种颜色外所有颜色均不饱和）
- 过度渐晕
````

### 8.7 图像合成规则

**成分规格：**
````
图像构图规则

三分法则：默认构图指南。将主体放置在交叉点。
居中：用于对称主题、产品英雄镜头、权威取景。
负空间：60% 以上的空白空间用于文本覆盖区域和喘息空间。
引导线：使用环境线将视线引导至焦点。
框架：使用前景元素来框架主题（门口、窗户、树枝）。
图层：使用前景、中景和背景元素创建深度。
黄金比例：用于有机、自然流动的组合物。

方向规则：
- 拍摄对象应面向构图，而不是面向边缘
- 移动的主体需要空间来“移动”
- 视线方向创造看不见的构图线

裁剪规则：
- 切勿在关节处剪裁（手腕、脚踝、膝盖、腰部、颈部）
- 接缝之间的裁剪以获得自然的框架
- 在头顶留出微空间（头部空间）
- 环境作物必须保持环境
````

### 8.8 摄影禁忌

**禁止拍照清单：**
````
摄影禁忌

切勿使用：
1. 库存照片陈词滥调：在会议桌上握手、指着屏幕的多元化团队、嘲笑沙拉的女人、独自一人高兴地跳起来
2. 严重过滤的图像：Instagram 风格的过滤器会扭曲颜色准确性
3. 带水印或低分辨率图像：不低于[最低分辨率]
4. 颜色等级不一致：一组照片中的每张照片必须与品牌颜色等级相匹配
5.强制多元化选角：多元化应该让人感觉自然且有代表性，而不是表演性的
6.过度修饰的皮肤：保留自然的皮肤纹理、毛孔和特征7.杂乱的背景：控制主体后面出现的内容
8. 荷兰角（倾斜的地平线）：除非是品牌创意方向的具体部分
9、景深过度模糊：脸部应该清晰；极端的散景看起来很业余
10. 文字烧入图像：文字应覆盖在布局中，而不是照片的一部分
11.混合照明温度：除非有意艺术化（温暖实用+凉爽环境）
12. 自拍品质的图像：所有品牌摄影都必须经过深思熟虑
````

---

## 模块 9：品牌应用——实际实施

品牌系统必须在现实世界中发挥作用——在纸上、墙上、卡车上、衬衫上。该模块定义了视觉识别如何转化为物理和数字接触点。

### 9.1 名片和文具

**它传达的信息：** 第一印象、个人信誉、对细节的关注。名片通常是某人持有的第一个实体品牌物品。感觉一定是故意的。

**设计规则：**
- 标准尺寸：3.5 x 2 英寸（美国）或 85 x 55 毫米（国际）
- 信息层次结构：姓名 > 职务 > 联系人 > 品牌
- 印刷加工选项增强品牌个性（凸版印刷、箔纸、边缘绘画、柔软触感）
- 留出喘息的空间——抵制填满每一毫米的冲动
- 定义完整的文具套件：名片、信笺、信封、记事卡、表扬单

**应用规范：**
````
名片规格：
尺寸：[尺寸]
方向：[水平/垂直]
纸材：[重量和表面处理 - 400gsm 哑光/600gsm 棉布/350gsm 无涂层]
印刷技术：[胶印/凸版印刷/数码/混合]
特殊加工：[烫金 / 盲浮雕 / SPOT UV / EDGE PAINTING / DIE CUT / NONE]
正面内容：[徽标、名称、标题、品牌元素]
背面内容：[联系信息/图案/实色/空白]
颜色模式：[CMYK / PANTONE -- 指定品牌颜色的 PMS 编号]
出血：【3mm标准】

全套文具套件：
信头：[A4/US Letter]、[STOCK]、[页眉/页脚位置]
信封：[尺寸]、[有窗/无窗]、[寄信人地址位置]
记事卡：[尺寸]、[折叠样式]、[内部打印]
````

**AI图像提示--名片模型：**
````
[品牌名称] 的高级名片模型。 [表面 - 深色大理石/浅色橡木桌子/混凝土/织物]上的[方向]卡。正面显示 [品牌印刷] 中的徽标和名称，并留有大量空白。 [特殊饰面 -- 金箔徽标/盲压花图案/徽标上的局部 UV/品牌颜色的边缘喷漆] 自然捕捉光线。背面显示[背面设计--联系方式/品牌图案/纯色品牌颜色]。多张卡片排列：一张面朝上，一张面朝下，一张倾斜显示边缘。自然柔和的定向照明创造出柔和的阴影。该卡片通过材料质量和内敛的设计传达[品牌定位——优质/现代/创意/专业]。 4K、商业产品摄影品质、优质印刷设计美学。
````

### 9.2 包装设计

**它传达的信息：** 品牌体验、拆箱时刻、货架展示。包装通常是品牌给人留下最强烈感官印象的地方——视觉、触觉、打开的声音，甚至气味。

**设计规则：**
- 货架影响：在拥挤的零售环境中必须在 3 米处可识别
- 层次结构：品牌标志 > 产品名称 > 主要优势 > 支持信息
- 材料选择与图形一样传达信息（牛皮纸=自然，哑光黑=优质）
- 可持续性考虑：可回收材料、最小化包装、清晰的处置说明
- 开箱体验：揭开的顺序很重要

**应用规范：**
````
包装规格：
包装类型：[盒/袋/瓶/管/袋/包装/罐]
尺寸：[尺寸]
材质：[瓦楞纸/折叠纸盒/硬盒/玻璃/铝/柔性薄膜]
表面处理：[哑光/光泽/柔软触感/纹理/牛皮纸/金属]
颜色模式：[CMYK / PANTONE / LIMITED COLORS--成本考虑]
标签与直接打印：[规格]
层次区域：
  主显示面板：徽标+产品名称+英雄视觉
  辅助面板：功能+优点+用途
  第三面板：成分/规格 + 法律 + 条形码可持续性：[材料来源/可回收性/FSC 认证/大豆油墨]
拆箱顺序：[客户首先看到的 -> 最后看到的]
````

**AI图像提示--包装设计：**
````
[品牌] [产品] 的优质包装设计模型。 [材料] 中的 [封装类型] 和 [表面处理]。使用[颜色/技术——烫金/压花/印刷]将品牌徽标突出地放置在[位置]。 [品牌排版] 中的产品名称。 [品牌颜色] 作为主色，带有 [强调] 细节。 [设计元素——简约干净的字体/大胆的图形图案/摄影窗口/插图]。包装位于 [SURFACE] 上，自然光投射出柔和的阴影。可见的支撑元素：[颜色]薄纸、感谢卡、品牌贴纸。拆箱体验给人一种[品牌形容词——优质/有趣/可持续/奢华]的感觉。 4K、商业包装摄影品质、Dieline奖美学。
````

### 9.3 标牌和寻路

**它传达的信息：** 实体存在、导航、空间品牌体验。标牌将品牌延伸到三维空间，并且必须在一定距离、一定速度和不同的光照条件下发挥作用。

**设计规则：**
- 易读距离：文字高度（英寸）x 50 = 可读距离（英尺）
- 高对比度：必须在阳光直射、夜间照明和雨中可读
- ADA/无障碍合规性：触觉元素、盲文、适当的高度
- 材料耐用性：户外标牌必须承受天气、紫外线和温度
- 寻路层次：目的地名称>方向>距离

**应用规范：**
````
标牌系统：
类型定义：
  主要标识：建筑物名称、入口、店面
  方向：箭头、路径、停车
  信息：时间、政策、联系方式
  监管：安全、合规、ADA
材质：[铝/亚克力/木材/金属制品/乙烯基]
��明：[无/前光/背光/光晕照明/边缘照明/霓虹灯]
安装方式：[墙壁/投影/独立/悬挂/纪念碑]
版式：[标牌专用字体（如果与品牌标准不同 - 针对距离进行优化）最小文字高度：[根据观看距离指定]
颜色：[高对比度 - 指定前景/背景组合]
````

**AI图像提示--标牌样机：**
````
[品牌名称] 的专业品牌标牌模型。 [材料]中的[标牌类型——外部建筑标牌/内部寻路/店面/纪念碑标牌]。 [照明——背光在黄昏的天空下发光/日光下的前光/光晕照明创造出优质的光芒]。品牌徽标和名称采用 [排版] 格式，比例适合 [观看距离]。安装在[表面——混凝土立面/玻璃店面/木质内墙]上。标牌通过材料质量和照明传达[品牌定位]。环境背景可见：[场景——城市街道/企业园区/零售购物中心/酒店大堂]。自然光照条件显示标志在现实环境中的读取方式。 4K、建筑标牌摄影品质、专业导视设计。
````

### 9.4 车辆和车队图形

**它传达的信息：** 移动品牌形象、专业性、影响力。品牌车辆是移动广告牌，在其进入的每个社区中代表该品牌。

**设计规则：**
- 速度下的可读性：名称/徽标必须能够从时速超过 30 英里的行驶汽车中识别出来
- 侧板是主要不动产；交通车辆后面板
- 避免使用小文本——如果在 20 英尺外无法阅读，请将其删除
- 大面积的品牌颜色可立即识别
- 包裹设计必须考虑门把手、车窗、轮舱和车身线条

**应用规范：**
````
车辆图形：
车辆类型：[轿车/货车/卡车/SUV/摩托车/自行车]
覆盖范围：[部分包裹/全部包裹/仅贴花/磁性标志]
主要信息：[徽标 + 名称 - 两侧始终可见]
次要消息：[网站/电话/标语——如果空间允许]
颜色覆盖范围：[车辆表面品牌颜色的百分比]
观看距离：近距离（5 英尺 - 细节）、中距离（20 英尺 - 消息）、远距离（50 英尺以上 - 颜色/形状识别）
门窗回避：[不可打印区域的地图]
材质：[乙烯基包裹/油漆/磁性/窗户性能]耐用性：[预期寿命 - 包裹 3-5 年]
````

**AI图像提示--车辆图形：**
````
[品牌] 的专业车辆包装设计。 [车辆类型]，[覆盖范围 - 全包裹/部分包裹]，[品牌颜色]。徽标在两侧显着显示，尺寸为 [SIZE for distance readability]。 [设计方法——干净的纯色块/动态流动图形/最小的仅徽标方法]。品牌颜色可从远处立即识别。车辆以轻微的 3/4 角停在[表面——干净的沥青/城市街道/品牌设施]上。自然日光准确显示包装颜色。干净的[排版]中的联系信息[包含/排除]。该车看起来很专业，代表着该品牌的自豪感。 4K、车辆包裹组合摄影品质。
````

### 9.5 商品和品牌产品

**它传达的信息：** 品牌忠诚度、归属感、生活方式的延伸。品牌商品将顾客变成品牌大使，将员工变成品牌载体。

**设计规则：**
- 产品质量反映品牌质量——廉价商品损害品牌认知度
- 标志位置：微妙而有品位（胸章、标签、同色系）与大胆（超大图形）
- 材料质量必须符合品牌定位（优质品牌=优质材料）
- 商品类别：服装、箱包、笔记本、饮料、科技配件、文具
- 联合品牌规则：当商品包含合作品牌时，定义层次结构

**应用规范：**
````
商品规格：
类别：
  服装：[T恤/连帽衫/帽子/夹克/袜子]
  配件：[手提袋/背包/笔记本/笔/水瓶/马克杯]
  技术：[手机壳/笔记本电脑内胆包/贴纸/USB 驱动器]
  办公室：[记事本/文件夹/挂绳/名牌]
质量等级：[高级/中档/促销]
标志应用：[刺绣/丝网印刷/热转印/凹凸/珐琅别针]
徽标位置：[左胸/中心/袖子/背面/仅标签]徽标尺寸：[SUBTLE -- <3 英寸/MEDIUM -- 3-6 英寸/BOLD -- 6+ 英寸或完整图形]
商品的调色板：[品牌颜色的子集 - 指定哪些颜色适用于面料/产品]
````

**AI图像提示--商品样机：**
````
[品牌名称] 的优质品牌商品系列。 [表面 - 干净的白色/大理石/木材] 上精心策划的平铺布置显示：[物品 - 带有微妙胸部徽标的 T 恤、带有品牌图案的手提包、带有浮雕封面的笔记本、珐琅别针、贴纸、马克杯]。 [品牌颜色] 中的所有商品均具有一致的徽标应用。 [标志技术——刺绣/丝网印刷/凹凸]细节可见。商品系列给人一种凝聚力和[品牌形容词——优质/俏皮/简约/精心制作]的感觉。自然柔和的灯光，头顶平躺构图。每个项目都可以用作独立的产品镜头。 4K、电商产品摄影品质、优质品牌商品美感。
````

### 9.6 贸易展览

**它传达的信息：** 行业影响力、品牌规模、沉浸式品牌体验。贸易展览将整个品牌体验压缩到一个物理空间中。

**设计规则：**
- 展位层次结构：品牌标识（50 英尺以上可读）> 产品/信息 > 参与度
- 背景必须作为社交媒体内容的摄影背景
- 灯光至关重要：品牌灯光色彩营造氛围
- 外卖材料：名片、宣传册、商品——全部品牌一致
- 数字集成：屏幕、交互式显示屏、连接物理与数字的二维码

**应用规范：**
````
展览规格：
展位尺寸：[10x10 / 10x20 / 20x20 / 定制——以英尺或米为单位]
展位类型：[POP-UP / MODULAR / CUSTOM BUILT / ISLAND]
高度元素：[横幅/塔楼/悬挂标志——用于距离可见度]
品牌标识高度：[展位顶部 - 50 英尺以上可读]
背景：【品牌墙--纯色+标志/图案/摄影/数码屏】
灯光：[品牌洗色/中性白/引人注目的聚光灯/LED 装饰]
材料：[织物张力/刚性面板/模块化系统/天然材料]互动：[屏幕/产品演示/VR/AR/照片机会]
宣传资料：[宣传册/名片/产品样品/商品赠品]
````

**人工智能图像提示--贸易展摊位：**
````
[品牌] 的专业贸易展览摊位设计。 [展位尺寸]展位以[品牌颜色]作为主导环境颜色。从整个展厅都可以看到顶部的大型品牌标识。干净的现代展位设计采用[材料——织物张力墙/光滑的面板/天然木材元素]。 【BACKDROP——发光标志品牌墙/大幅产品摄影/动态数码屏]。品牌照明铸造[颜色]环境发光。产品展示区域采用[灯光处理]。开放且诱人的平面图。工作人员穿着品牌[服装]。带有[互动元素]的访客互动区。展位通过空间设计品质传达[品牌定位]。 4K、贸易展览摄影品质、优质展览设计美学。
````

### 9.7 制服和服装

**它传达的信息：** 团队认同、专业精神、品牌体现。当人们穿着该品牌时，他们就成为了该品牌。统一设计必须平​​衡品牌表达与舒适性、功能性和尊严。

**设计规则：**
- 舒适和功能第一——没有人能用不舒服的衣服很好地代表一个品牌
- 通过颜色和微妙的细节而不是巨大的标志来展现品牌形象
- 定义着装要求等级：正式（面向客户）、商务休闲（办公室）、休闲（活动）、野外（户外/劳动）
- 包容性尺码是强制性的（不是事后才想到的）
- 季节变化：温暖天气和寒冷天气选项

**应用规范：**
````
制服/服装规格：
等级：
  正装：[品牌颜色西装/西装外套，品牌配饰]
  商务休闲：【POLO/BUTTON-DOWN绣花标志、品牌腰带/围巾】
  休闲：【带品牌标志的T恤/帽衫，舒适合身】
  领域：[具有高可见度品牌标识的耐用外套]
标志应用：[刺绣左��——所有级别的标准]
调色板：[批准的服装颜色——品牌调色板的子集]
面料质量：[规格——重量、混纺、性能特点]包容性尺码：[XS-5XL 最小范围/针对特殊角色的定制配件]
配件：[挂绳/名牌/帽子/围巾/腰带——品牌商品]
保养说明：[洗涤以保持品牌外观]
````

**AI图像提示--统一设计：**
````
[BRAND NAME] 的专业品牌制服系列。 [人体模型/模特] 上显示三种服装层次：正装（带有 [BRAND COLOR] 口音的定制西装外套）、商务休闲装（左胸带有刺绣徽标的优质 Polo 衫）和休闲装（带有雅致品牌标志的高级 [BRAND COLOR] T 恤）。干净的工作室摄影，具有中性背景。 [品牌颜色] 作为统一的线索在所有层级中一致出现。面料品质可见——优质材料自然发光。这些制服看起来像是人们会选择穿的衣服，而不是机构服装。包容性贴合得到体现。 4K、时尚画册品质、工作服与品牌设计美学的结合。
````

