定位：[一句话——品牌是什么以及它服务的对象]

个性：[3-5 个形容词特征]
声音：[3 个描述——例如，自信、热情、直接]

徽标：[显示主要徽标]
不要：[三大标志规则——拉伸、重新着色、添加效果]

原色：
  [颜色 1]：[样本] [十六进制] [PANTONE]
  [颜色 2]：[样本] [十六进制] [PANTONE]
  [强调]：[样本] [十六进制] [PANTONE]

版式：
  标题：[字体名称、粗细]
  正文：[字体名称、粗细]

图像：[用一句话描述摄影/插图风格]

联系方式：[品牌团队电子邮件/Slack 提问]
````

**AI图像提示——一页品牌摘要：**
````
[品牌名称] 的专业单页品牌摘要表。干净的 A4/Letter 布局一目了然地显示完整的品牌：顶部徽标、[品牌排版] 中的使命宣言、具有十六进制和 Pantone 值的调色板样本、主要和次要字体样本、摄影风格缩略图和关键品牌规则。所有内容都位于一个页面上，具有大量的空白和清晰的视觉层次结构。摘要本身展示了它所描述的品牌指南——使用品牌自己的颜色、字体和布局风格。使用 [整理] 在 [纸张] 上打印。 4K，品牌准则品质，优雅的单页设计。
