## 附录 B：品牌设计术语表

````
品牌设计术语

品牌架构：子品牌、产品和服务与母品牌的关系
  （Branded House：全部属于一个品牌/House of Brands：独立品牌/Endorsed：母公司认可子品牌）

品牌资产：源自消费者对品牌名称的认知的商业价值

品牌指南：管理如何使用品牌元素的规则文件（本文件）

品牌标志：徽标的符号或图标部分，与文字商标分开

清晰空间：徽标周围没有其他元素可以进入的最小空白区域

CMYK：青色、品红色、黄色、基色（黑色）——印刷生产的颜色模型

色温：颜色的暖色或冷色，以开尔文 (K) 为单位测量

设计令牌：连接设计和代码的命名值（颜色、间距、半径）

黄金比例：用于美观比例的数学比例 (~1.618)

GUTTER：网格系统中列之间的空间

十六进制代码：颜色的六位字母数字表示形式 (#FF5733)

字距调整：调整特定字母对之间的间距以实现视觉和谐

LEADING：文本行之间的间距（行间间距）

锁定：品牌元素（徽标+字标+标语）的固定排列，不得更改

MOOD BOARD：视觉拼贴为品牌确立审美方向

负空间：设计中的空白空间，有意用作设计元素

PANTONE (PMS)：彩通匹配系统——印刷的标准化色彩通信

响应式设计：适应不同屏幕尺寸和设备的设计

专色：单一预混合墨水颜色（相对于 CMYK 印刷）可实现精确的颜色匹配

跟踪：统一调整单词或行中所有字母之间的间距

版式层次结构：组织文本的视觉层次系统（H1、H2、正文、标题）

视觉识别：代表品牌的完整视觉元素集

WCAG：网页内容可访问性指南——国际可访问性标准

X-HEIGHT：小写字母的高度（由字母“x”测量），确定感知大小
````

