INSERT INTO skill (name, description, content, source, sort_order, cover_url, skill_code, version, is_delete, gmt_create, gmt_modified)
VALUES ('Villain Duel Climax Finisher Creation Guide', '生成对话驱动的英雄与反派战斗高潮脚本，实现电影般的终结、对手对决和动漫风格的战斗结局。用于编写 AAA 游戏风格的执行和故事板提示的脚本。', '---
name: Villain Duel Climax Finisher Creation Guide
description: "生成对话驱动的英雄与反派战斗高潮脚本，实现电影般的终结、对手对决和动漫风格的战斗结局。用于编写 AAA 游戏风格的执行和故事板提示的脚本。"
version: 0.1.0
---
## 说明
生成优先考虑情绪升级和视觉冲击的战斗高潮序列。每个脚本必须遵循以下顺序：

1. **反派统治：** 通过优越的定位和攻击时持续的嘲讽对话来建立反派的控制权。
2. **战斗对话：** 将对话与动作交织在一起。恶棍必须攻击英雄的信仰，而英雄必须用简短而有影响力的台词来回应。
3. **压力下的英雄：** 迫使英雄陷入情绪和身体的低谷。 
4. **意识形态冲突：** 呈现一场尖锐、简洁的辩论，英雄拒绝反派的世界观。
5. **英雄亮点台词：** 英雄发表了一个明确的简短声明，引发了逆转。6. **权力逆转：** 改变战斗节奏、镜头视角（低角度）和视觉环境来指示英雄的转变。
7. **AAA 式终结器：** 构建具有四个不同阶段的终结器：断点、锁定、冲击爆发和胜利冻结。
8. **反派怀疑：** 描述反派对失败的反应，重点是心理崩溃或怀疑。
9. **英雄胜利保持：** 以克制的、电影般的姿势或动作结束，强调英雄的决心。

## 何时使用
- **适用：** 创建最终 Boss 阶段突破、对手对决、机甲或奇幻决斗结局，以及用于 AI 视频/故事板生成的脚本。
- **不适用：** 从开始到结束的完整战斗编排、1vN 战斗或低风险小冲突。

## 输出要求
- 保持剧本简洁并注重电影节奏。
- 包括摄像机角度、声音设计和视觉反馈的具体细节（例如，装甲断裂、能量扭曲）。
- 严格遵守非血腥表达政策。

## 示例
- **英雄亮点台词：** “你认为自己的力量是绝对的，因为你从来没有什么可以保护的。今天，你输给了你丢弃的一件东西。”
- **恶棍怀疑：**“当恶棍看着自己破碎的武器时，他们的冷笑开始颤抖，他们睁大了眼睛，意识到他们的核心意识形态失败了。”
- **胜利保持：**“英雄收起剑鞘，战场声音逐渐减弱为沉闷的嗡嗡声，他们背对着摇摇欲坠的老板。”
', 'official', 92, NULL, 'cn92', 0, 0, NOW(), NOW());
INSERT INTO skill (name, description, content, source, sort_order, cover_url, skill_code, version, is_delete, gmt_create, gmt_modified)
VALUES ('Cinematic Disaster Movie Creation Guide', '起草电影灾难电影剧本和序列，具有根深蒂固的张力、逻辑结构失败和 IMAX 规模的制作价值。用于剧本写作、故事板和创意场景规划。', '---
name: Cinematic Disaster Movie Creation Guide
description: "起草电影灾难电影剧本和序列，具有根深蒂固的张力、逻辑结构失败和 IMAX 规模的制作价值。用于剧本写作、故事板和创意场景规划。"
version: 0.1.0
---
## 说明
当负责创建灾难序列时，请遵循以下程序步骤：

1. **建立平静：** 从普通的场景开始，让观众接地气。
2. **通过逻辑升级：** 按照以下顺序设计灾难：警告（微妙线索）-> 点火（影响点）-> 局部崩溃-> 大范围升级。
3. **整合人类风险：** 确保每个序列都包含特定的角色选择（例如，营救与逃脱）以及依赖于判断或环境交互的英雄行动。
4. **应用电影语言：** 对于每个节拍，定义摄像机角度、灯光和声音。5. **维持物质性：** 确保破坏遵循因果关系（例如，结构故障导致碎片，从而迫使路线改变）。
6. **用钩子结束：** 以暂时的生存时刻结束序列，然后是暗示更大威胁的后果钩子。

## 何时使用
### 适用场景
- 编写灾难电影场景脚本。
- 为灾难场面创建故事板大纲。
- 为电影制作开发叙事提示。
- 规划自然或科幻灾难的结构进展。

### 不适用场景
- 请勿用于生成暴力或血腥画面。
- 请勿用于现实世界的安全说明或应急计划。
- 请勿用于生成宣扬非法行为的内容。

## 输出要求
- **物理逻辑：** 用结构失效和材料碎片来描述破坏。
- **以人为本：** 关注情感利益和决策。
- **生产就绪：** 包括适合创意可视化的特定摄像机、声音和灯光细节。

## 示例
**提示：**“桥梁倒塌序列。”
- **视觉：** 桥梁吊索振动的低角度镜头，其中一根吊索发出剧烈的鞭裂声。
- **人类赌注：** 主角选择帮助受困的通勤者走向稳定的柱子，而不是跳到附近的海岸。
- **视觉特效细节：** 混凝土碎片落入河中，尘埃云遮蔽了地平线，透过烟雾可以看到紧急车辆的灯光。
- **相机：** 从桥面的长焦压缩镜头开始，过渡到主角身后的手持跟踪镜头。
', 'official', 93, NULL, 'cn93', 0, 0, NOW(), NOW());
