INSERT INTO skill (name, description, content, source, sort_order, cover_url, skill_code, version, is_delete, gmt_create, gmt_modified)
VALUES ('Story Sharing Talking Video Toolkit', '为个人讲故事、情感叙述和叙事视频提供专业指导。在规划或审查视频美学、节奏和表演基调以分享个人经验时使用此功能。', '---
name: Story Sharing Talking Video Toolkit
description: "为个人讲故事、情感叙述和叙事视频提供专业指导。在规划或审查视频美学、节奏和表演基调以分享个人经验时使用此功能。"
version: 0.1.0
---
## 说明
注重情感沉浸，所有视觉和表演元素都服务于叙事。保持真诚、自然的状态；避免刚性结构。

### 负面约束（强制）
在所有的策划中，要避免：虚假的情感、夸张的耸人听闻的表情、僵硬的动作、过度修饰的面孔、塑料纹理、过饱和的色彩、嘈杂的场景、花哨的特效以及凌乱或重叠的字幕。

## 何时使用
### 适用场景
- 为生活故事、个人成长经历或情感叙述规划视觉和表演基调。
- 设置“头部说话”讲故事视频的情绪和氛围。

### 请勿用于
- 高能量的促销内容或商业广告。
- 快速剪辑的娱乐或高强度的视频博客。
- 需要技术屏幕覆盖的复杂教程。

## 工作流程
1. **定义色调**：在温暖治愈（温和/低饱和度）、平静重述（克制/中性）或深层情感（暗淡/低对比度）之间进行选择。
2. **设置视角**：选择平视以进行交流，或选择低角度以营造稳定、专业的氛围。
3. **选择环境**：将IP风格（学术/学习、日常/家庭或精英/户外）与故事内容相匹配。
4. **应用节奏**：通过缓慢、微妙的浮动或变焦控制镜头移动，以匹配叙事转折点；避免���繁的角度切换。

## 输出要求
- **视觉效果**：保持静态或微妙、不分散注意力的背景。
- **表达**：使用真实、放松的面部肌肉和自然的眼神交流。
- **排版**：保持字幕最少、透明度低，并在风格上与叙事情绪保持一致。

## 示例
- **温馨的生活故事**：应用柔和的家庭灯光、温和的目光接触以及缓慢、浮动的镜头节奏。
- **平静的体验重述**：使用极简、安静的学习背景，中性的语气和稳定、均匀的表情。
- **深度情感分享**：利用昏暗、分层的柔和灯光和缓慢、深思熟虑的相机变焦来强调关键的叙事时刻。
', 'official', 95, NULL, 'cn95', 0, 0, NOW(), NOW());
INSERT INTO skill (name, description, content, source, sort_order, cover_url, skill_code, version, is_delete, gmt_create, gmt_modified)
VALUES ('Live Stream Clip Talking Video Toolkit', '提供用于编辑直播亮点、问答摘录和辅助内容的风格指南和结构框架，同时保持真实、即兴的广播氛围。', '---
name: Live Stream Clip Talking Video Toolkit
description: "提供用于编辑直播亮点、问答摘录和辅助内容的风格指南和结构框架，同时保持真实、即兴的广播氛围。"
version: 0.1.0
---
## 说明
应用这些指令来优化直播片段。专注于保留自然、无脚本的纹理，而不是实现抛光的工作室外观。

### 核心创意限制
- **真实性：** 优先考虑自然的说话节奏。避免照本宣科、机械化或过度修饰的交付方式。
- **视觉完整性：** 保持一致的照明和摄像机角度，以反映实时广播环境。
- **负面约束：** 确保输出避免：死板的背诵、虚假的平滑、僵硬的表情、过度修饰的面部、塑料纹理、静态框架或分散注意力的高动态背景。

### 演示和相机指南
- **情绪基调：** 将强度与上下文相匹配（例如，日常聊天放松，专业输出稳定，互动片段充满活力）。
- **相机语言：** 喜欢标准的视线水平或稍微低角度的拍摄。使用微动作（微妙的头部运动、温和的变焦）来强调核心观点，而不是频繁的角度切换。
- **设置和氛围：** 将环境（背景、灯光）与 IP 类型（例如，极简/学术的知识、柔和/氛围的生活方式）保持一致。- **表达：** 强调即兴、自然的反应，包括思考停顿、自然的微笑以及与说话节奏相一致的反应性手势。
- **文本/字幕：** 使用最少的、可读的覆盖层。专注于核心观点亮点或干净、同步的完整字幕。避免杂乱、重叠或多余的装饰。

## 何时使用
### 适用场景
- 从直播录制中创建精彩片段。
- 编辑社交平台的问答片段。
- 提炼即兴内容以进行二次分发。
- 标准化重复直播系列的视觉/音调呈现。

### 不适用场景
- 创建有脚本的、预先录制的广告或高制作广告。
- 动画非实时内容或人工智能生成的合成头像。
- 用非原创材料替换现有背景或音频资产。

## 示例
- **休闲聊天：** 使用轻松的灯光、自然的即兴说话节奏和中特写镜头来保持温暖、亲密的氛围。
- **专业输出：** 应用明亮、均匀的照明、稳定的固定镜头取景和简洁的关键句子文本突出显示。
- **互动问答：** 利用生动的表情、反应灵敏的手势以及充满活力、清晰的视听对齐。
', 'official', 96, NULL, 'cn96', 0, 0, NOW(), NOW());
